def app_dir() -> Path:
    if getattr(sys, "frozen", False):
        return Path(sys.executable).resolve().parent
    return Path(__file__).resolve().parent


def find_ytdlp() -> str:
    d = app_dir()
    for name in ("yt-dlp.exe", "yt-dlp", "yt-dlp.cmd"):
        p = d / name
        if p.exists():
            return str(p)
    return shutil.which("yt-dlp") or "yt-dlp"



class _PROCESSENTRY32W(ctypes.Structure):
    _fields_ = (
        ("dwSize", ctypes.c_uint32),
        ("cntUsage", ctypes.c_uint32),
        ("th32ProcessID", ctypes.c_uint32),
        ("th32DefaultHeapID", ctypes.c_void_p),
        ("th32ModuleID", ctypes.c_uint32),
        ("cntThreads", ctypes.c_uint32),
        ("th32ParentProcessID", ctypes.c_uint32),
        ("pcPriClassBase", ctypes.c_long),
        ("dwFlags", ctypes.c_uint32),
        ("szExeFile", ctypes.c_wchar * 260),
    )


def _parent_is_launcher() -> bool:
    """判断父进程是否为 XX Down 启动器（安装版由启动器拉起 pythonw）"""
    try:
        pid = os.getppid()
        k32 = ctypes.windll.kernel32
        k32.CreateToolhelp32Snapshot.restype = ctypes.c_void_p
        snap = k32.CreateToolhelp32Snapshot(0x00000002, 0)
        if not snap or snap == 0xFFFFFFFFFFFFFFFF:
            return False
        try:
            pe = _PROCESSENTRY32W()
            pe.dwSize = ctypes.sizeof(_PROCESSENTRY32W)
            if not k32.Process32FirstW(snap, ctypes.byref(pe)):
                return False
            while True:
                if pe.th32ProcessID == pid:
                    return pe.szExeFile.lower().endswith("xx down.exe")
                if not k32.Process32NextW(snap, ctypes.byref(pe)):
                    return False
        finally:
            k32.CloseHandle(snap)
    except Exception:
        return False


def find_ffmpeg_dir():
    d = app_dir()
    if (d / "ffmpeg.exe").exists():
        return str(d)
    if shutil.which("ffmpeg"):
        return None
    return None


def default_download_dir() -> str:
    home = Path.home()
    for cand in (home / "Downloads", home / "下载"):
        if cand.exists():
            return str(cand)
    return str(home)


def parse_conf_defaults():
    """从 yt-dlp.conf 中读取默认的文件名模板和 cookies 文件路径"""
    template, cookie_file = DEFAULT_TEMPLATE, None
    conf = app_dir() / "yt-dlp.conf"
    if conf.exists():
        try:
            for line in conf.read_text(encoding="utf-8", errors="replace").splitlines():
                line = line.strip()
                if not line or line.startswith("#"):
                    continue
                if line.startswith("-o ") or line.startswith("--output "):
                    val = line.split(None, 1)[1].strip().strip('"')
                    base = os.path.basename(val)
                    if base:
                        template = base
                elif line.startswith("--cookies "):
                    val = line.split(None, 1)[1].strip().strip('"')
                    cookie_file = val if os.path.isabs(val) else str(app_dir() / val)
        except Exception:
            pass
    return template, cookie_file


