def settings_path() -> Path:
    return app_dir() / "ytdlp_gui_settings.json"


def load_settings() -> dict:
    s = dict(DEFAULT_SETTINGS)
    s["download_dir"] = default_download_dir()
    tpl, ck = parse_conf_defaults()
    s["template"] = tpl
    s["cookie_file"] = ck or str(app_dir() / "cookies.txt")
    p = settings_path()
    if p.exists():
        try:
            data = json.loads(p.read_text(encoding="utf-8"))
            if isinstance(data, dict):
                for k in list(s.keys()):
                    if k in data:
                        s[k] = data[k]
        except Exception:
            pass
    return s


def save_settings(s: dict):
    try:
        settings_path().write_text(
            json.dumps(s, ensure_ascii=False, indent=2), encoding="utf-8")
    except Exception:
        pass


def format_selector(quality: str, audio_quality: str) -> str:
    """根据画质/音质生成 yt-dlp 的 -f 格式选择器"""
    cap = _AUDIO_BITRATE.get(audio_quality)
    if quality == "仅音频":
        return f"bestaudio[abr<={cap}]/bestaudio/best" if cap else "bestaudio/best"
    if quality == "最佳画质（MP4优先）":
        audio = f"bestaudio[ext=m4a][abr<={cap}]" if cap else "bestaudio[ext=m4a]"
        return f"bestvideo[ext=mp4]+{audio}/best[ext=mp4]/best"
    h = _QUALITY_HEIGHT.get(quality)
    if h:
        video, fallback = f"bestvideo[height<={h}]", f"best[height<={h}]"
    else:
        video, fallback = "bestvideo", "best"
    audio = f"bestaudio[abr<={cap}]" if cap else "bestaudio"
    return f"{video}+{audio}/{fallback}"


