def build_download_args(urls, s: dict):
    args = [
        find_ytdlp(),
        "--ignore-config",
        "--paths", "home:" + s["download_dir"],
        "-o", s["template"],
        "-f", format_selector(s["quality"], s["audio_quality"]),
    ]
    ffdir = find_ffmpeg_dir()
    if ffdir:
        args += ["--ffmpeg-location", ffdir]
    if s["container"] == "MP4":
        args += ["--merge-output-format", "mp4"]
    elif s["container"] == "MKV":
        args += ["--merge-output-format", "mkv"]
    if s["subs"]:
        args += ["--write-auto-sub", "--sub-langs", s["sub_lang"] or "zh,en"]
        if s["convert_subs"]:
            args += ["--convert-subs", "srt"]
    if s["thumbnail"]:
        args += ["--write-thumbnail", "--convert-thumbnail", "png"]
    if s.get("no_playlist"):
        args += ["--no-playlist"]
    mode = s.get("cookie_mode")
    if mode == "file" and s.get("cookie_file"):
        args += ["--cookies", s["cookie_file"]]
    elif mode == "browser" and s.get("browser"):
        args += ["--cookies-from-browser", s["browser"].lower()]
    args += urls
    return args


def build_test_args(urls, s: dict):
    return build_download_args(urls, s) + ["--simulate", "--skip-download"]


def find_browser_exe(browser):
    if browser == "chrome":
        cands = (r"%ProgramFiles%\Google\Chrome\Application\chrome.exe",
                 r"%ProgramFiles(x86)%\Google\Chrome\Application\chrome.exe",
                 r"%LOCALAPPDATA%\Google\Chrome\Application\chrome.exe")
    elif browser == "edge":
        cands = (r"%ProgramFiles%\Microsoft\Edge\Application\msedge.exe",
                 r"%ProgramFiles(x86)%\Microsoft\Edge\Application\msedge.exe")
    else:
        return None
    for c in cands:
        p = os.path.expandvars(c)
        if os.path.exists(p):
            return p
    return None


def browser_profile_root(browser):
    la = os.environ.get("LOCALAPPDATA", "")
    if browser == "chrome":
        return Path(la) / "Google" / "Chrome" / "User Data"
    if browser == "edge":
        return Path(la) / "Microsoft" / "Edge" / "User Data"
    return None


def free_port():
    with socket.socket() as s:
        s.bind(("127.0.0.1", 0))
        return s.getsockname()[1]


class _MiniWebSocket:
    """极简 WebSocket 客户端，用于 Chrome DevTools 协议通信"""

    def __init__(self, url):
        rest = url.split("://", 1)[1]
        hostport, _, path = rest.partition("/")
        host, _, port = hostport.partition(":")
        self.sock = socket.create_connection((host, int(port)), timeout=10)
        key = base64.b64encode(os.urandom(16)).decode()
        req = ("GET /%s HTTP/1.1\r\nHost: %s:%s\r\nUpgrade: websocket\r\n"
               "Connection: Upgrade\r\nSec-WebSocket-Key: %s\r\n"
               "Sec-WebSocket-Version: 13\r\n\r\n" % (path, host, port, key))
        self.sock.sendall(req.encode())
        resp = b""
        while b"\r\n\r\n" not in resp:
            chunk = self.sock.recv(4096)
            if not chunk:
                break
            resp += chunk
        if b" 101 " not in resp.split(b"\r\n", 1)[0]:
            raise RuntimeError("WebSocket 连接失败")

    def _exact(self, n):
        buf = b""
        while len(buf) < n:
            chunk = self.sock.recv(n - len(buf))
            if not chunk:
                raise RuntimeError("连接已断开")
            buf += chunk
        return buf

    def send(self, obj):
        data = json.dumps(obj).encode()
        mask = os.urandom(4)
        head = bytearray([0x81])
        if len(data) < 126:
            head.append(0x80 | len(data))
        elif len(data) < 65536:
            head.append(0x80 | 126)
            head += struct.pack(">H", len(data))
        else:
            head.append(0x80 | 127)
            head += struct.pack(">Q", len(data))
        masked = bytes(b ^ mask[i % 4] for i, b in enumerate(data))
        self.sock.sendall(bytes(head) + mask + masked)

    def recv(self, timeout=30):
        self.sock.settimeout(timeout)
        h = self._exact(2)
        opcode = h[0] & 0x0F
        ln = h[1] & 0x7F
        if ln == 126:
            ln = struct.unpack(">H", self._exact(2))[0]
        elif ln == 127:
            ln = struct.unpack(">Q", self._exact(8))[0]
        mask = self._exact(4) if (h[1] & 0x80) else None
        payload = self._exact(ln)
        if mask:
            payload = bytes(b ^ mask[i % 4] for i, b in enumerate(payload))
        if opcode == 0x9:  # ping -> pong
            self.sock.sendall(bytes([0x8A, len(payload)]) + payload)
            return None
        if opcode == 0x1:
            return payload.decode(errors="replace")
        return None


def find_running_debug(ports=None):
    """查找经典调试端口（兜底用），返回 (端口, 页面WebSocket地址)"""
    if ports is None:
        ports = list(range(9222, 9241))
    for port in ports:
        try:
            with urllib.request.urlopen("http://127.0.0.1:%d/json/list" % port, timeout=2) as r:
                targets = json.loads(r.read().decode())
            for t in targets:
                if t.get("type") == "page" and t.get("webSocketDebuggerUrl"):
                    return port, t["webSocketDebuggerUrl"]
        except Exception:
            continue
    return None, None


def read_devtools_active_port(browser):
    """读取 Chrome/Edge 的 DevToolsActivePort 文件，返回 (端口, 调试路径)"""
    root = browser_profile_root(browser)
    if not root:
        return None, None
    f = root / "DevToolsActivePort"
    try:
        lines = f.read_text(encoding="utf-8").strip().splitlines()
        if lines:
            port = int(lines[0].strip())
            path = lines[1].strip() if len(lines) > 1 and lines[1].strip().startswith("/") else "/devtools/browser"
            return port, path
    except Exception:
        pass
    return None, None


def grab_cookies_via_page(page_ws, urls=("https://www.youtube.com",)):
    """通过已连接的页面目标读取 Cookie（经典端口兜底），返回 (Netscape文本, 错误)"""
    try:
        ws = _MiniWebSocket(page_ws)
    except Exception as e:
        return None, "连接浏览器失败：%s" % e
    try:
        ws.send({"id": 1, "method": "Network.enable"})
        ws.send({"id": 2, "method": "Network.getCookies", "params": {"urls": list(urls)}})
        result = None
        deadline = time.time() + 40
        while time.time() < deadline:
            msg = ws.recv()
            if not msg:
                continue
            try:
                obj = json.loads(msg)
            except Exception:
                continue
            if obj.get("id") == 2:
                result = obj
                break
        if not result:
            return None, "获取 Cookie 超时（请检查浏览器是否弹出“允许远程调试？”并点击允许）"
        if "error" in result:
            return None, "获取 Cookie 失败：%s" % result["error"].get("message", "")
        cookies = result["result"].get("cookies", [])
        return _cookies_to_netscape(cookies, "浏览器里没有找到相关网站的 Cookie（请确认已登录目标网站）")
    finally:
        try:
            ws.sock.close()
        except Exception:
            pass


def _cookies_to_netscape(cookies, empty_msg):
    if not cookies:
        return None, empty_msg
    lines = ["# Netscape HTTP Cookie File", "# Generated by yt-dlp downloader"]
    for c in cookies:
        dom = c.get("domain", "")
        if not dom:
            continue
        try:
            exp = int(c.get("expires", 0) or 0)
        except Exception:
            exp = 0
        if exp < 0:
            exp = 0
        lines.append("\t".join([
            dom,
            "TRUE" if dom.startswith(".") else "FALSE",
            c.get("path", "/"),
            "TRUE" if c.get("secure") else "FALSE",
            str(exp),
            c.get("name", ""),
            c.get("value", ""),
        ]))
    return "\n".join(lines) + "\n", None


def grab_browser_cookies(browser, urls=("https://www.youtube.com",)):
    """通过 Chrome/Edge 官方调试通道（autoConnect）读取运行中浏览器的 Cookie"""
    port, path = read_devtools_active_port(browser)
    if not port:
        cport, page_ws = find_running_debug()
        if page_ws:
            return grab_cookies_via_page(page_ws, urls)
        return None, "未发现调试端口（请确认已在 chrome://inspect 打开 Remote debugging 开关并保持浏览器运行）"
    try:
        ws = _MiniWebSocket("ws://127.0.0.1:%d%s" % (port, path))
    except Exception as e:
        return None, "连接调试端口失败：%s（若浏览器弹出“允许远程调试？”，请点击允许后重试）" % e
    try:
        ws.send({"id": 1, "method": "Target.getTargets"})
        targets = None
        deadline = time.time() + 15
        while time.time() < deadline and targets is None:
            msg = ws.recv()
            if not msg:
                continue
            try:
                obj = json.loads(msg)
            except Exception:
                continue
            if obj.get("id") == 1:
                targets = obj
        if not targets or "error" in targets:
            return None, "获取浏览器目标失败"
        pages = [t for t in targets["result"].get("targetInfos", []) if t.get("type") == "page"]
        if not pages:
            return None, "浏览器中没有页面标签（请先打开任意网页）"
        ws.send({"id": 2, "method": "Target.attachToTarget",
                 "params": {"targetId": pages[0]["targetId"], "flatten": True}})
        session_id = None
        deadline = time.time() + 15
        while time.time() < deadline and session_id is None:
            msg = ws.recv()
            if not msg:
                continue
            try:
                obj = json.loads(msg)
            except Exception:
                continue
            if obj.get("id") == 2:
                if "error" in obj:
                    return None, "附加页面失败：%s" % obj["error"].get("message", "")
                session_id = obj["result"].get("sessionId")
        if not session_id:
            return None, "附加页面失败（超时）"
        ws.send({"id": 3, "sessionId": session_id, "method": "Network.enable"})
        ws.send({"id": 4, "sessionId": session_id, "method": "Network.getCookies",
                 "params": {"urls": list(urls)}})
        result = None
        deadline = time.time() + 20
        while time.time() < deadline and result is None:
            msg = ws.recv()
            if not msg:
                continue
            try:
                obj = json.loads(msg)
            except Exception:
                continue
            if obj.get("id") == 4:
                result = obj
        if not result:
            return None, "获取 Cookie 超时"
        if "error" in result:
            return None, "获取 Cookie 失败：%s" % result["error"].get("message", "")
        cookies = result["result"].get("cookies", [])
        return _cookies_to_netscape(cookies, "浏览器里没有找到相关网站的 Cookie（请确认已登录目标网站）")
    finally:
        try:
            ws.sock.close()
        except Exception:
            pass

def open_page_via_debug(port, path, url):
    """通过浏览器调试通道打开一个页面（让 Chrome 自己打开，最可靠）"""
    try:
        ws = _MiniWebSocket("ws://127.0.0.1:%d%s" % (port, path))
    except Exception:
        return False
    try:
        ws.send({"id": 1, "method": "Target.createTarget", "params": {"url": url}})
        deadline = time.time() + 10
        while time.time() < deadline:
            msg = ws.recv()
            if not msg:
                continue
            try:
                obj = json.loads(msg)
            except Exception:
                continue
            if obj.get("id") == 1:
                return "error" not in obj
        return False
    finally:
        try:
            ws.sock.close()
        except Exception:
            pass


# ============================ 抖音（浏览器拦截模式，借鉴“猫抓”思路） ============================
def is_douyin_url(url):
    return bool(re.search(r"douyin\.com", url, re.I))


def dy_normalize_url(url):
    """把抖音分享链接归一化为标准 /video/<id> 形式（modal_id 式）"""
    m = re.search(r"[?&]modal_id=(\d+)", url)
    if m:
        return "https://www.douyin.com/video/" + m.group(1)
    return url


DY_UA = ("Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 "
         "(KHTML, like Gecko) Chrome/120.0.0.0 Safari/537.36")


def _dy_ttwid_path() -> Path:
    return app_dir() / "dy_ttwid.json"


def dy_get_ttwid(log=None):
    """获取 ttwid cookie（非登录态，只是设备标识，抖音 web API 的准入门槛）。
    ttwid 有效期 1 年，本地缓存 30 天；缺失时通过字节公开注册端点获取。"""
    def _log(s):
        if log:
            log(s)
    p = _dy_ttwid_path()
    if p.exists():
        try:
            d = json.loads(p.read_text(encoding="utf-8"))
            if d.get("ttwid") and time.time() < d.get("expire", 0):
                return d["ttwid"]
        except Exception:
            pass
    body = json.dumps({
        "region": "cn", "aid": 6383, "needFid": False,
        "service": "www.douyin.com",
        "migrate_info": {"ticket": "", "source": "node"},
        "cbUrlProtocol": "https", "union": True,
    }).encode()
    req = urllib.request.Request(
        "https://ttwid.bytedance.com/ttwid/union/register/",
        data=body,
        headers={"User-Agent": DY_UA, "Content-Type": "application/json"})
    with urllib.request.urlopen(req, timeout=20) as r:
        setc = r.headers.get("Set-Cookie", "")
    ttwid = ""
    for part in setc.split(","):
        if "ttwid=" in part:
            ttwid = part.split("ttwid=", 1)[1].split(";", 1)[0]
    if not ttwid:
        raise RuntimeError("注册响应未返回 ttwid")
    try:
        p.write_text(json.dumps({"ttwid": ttwid, "expire": time.time() + 30 * 86400}),
                     encoding="utf-8")
    except Exception:
        pass
    _log("✓ 已获取 ttwid（本地缓存，30 天内有效）")
    return ttwid


def dy_extract_video_id(url):
    """从抖音链接提取 aweme 视频 ID（长链 / 短链 / modal_id / 图文 note）"""
    m = (re.search(r"/(?:video|note)/(\d{5,})", url)
         or re.search(r"[?&]modal_id=(\d+)", url)
         or re.search(r"/share/video/(\d+)", url))
    if m:
        return m.group(1)
    try:
        req = urllib.request.Request(url, headers={"User-Agent": DY_UA})
        with urllib.request.urlopen(req, timeout=20) as r:
            final = r.geturl()
            body = r.read(65536).decode("utf-8", "ignore")
        for text in (final, body):
            m = (re.search(r"/(?:video|note)/(\d{5,})", text)
                 or re.search(r"[?&]modal_id=(\d+)", text))
            if m:
                return m.group(1)
    except Exception:
        pass
    return None


def _dy_bitrate_to_formats(video):
    """解析 video.bit_rate + video.play_addr 为画质列表。
    按分辨率去重（保留文件更大的流），分辨率降序排列。
    竖屏视频的 p 值取短边 min(width, height)，与 gear 命名口径一致。"""
    duration = video.get("duration") or 0

    def _est_size(p):
        if not duration:
            return 0
        bps = 2000000
        if p >= 1080:
            bps = 5000000
        elif p >= 720:
            bps = 2500000
        elif p >= 480:
            bps = 1500000
        elif p >= 360:
            bps = 800000
        return int(bps * duration / 1000 / 8)

    def _eff_p(w, h, gear_num):
        if w and h:
            return min(w, h)
        return h or w or gear_num or 0

    fmts = {}
    for x in (video.get("bit_rate") or []):
        pa = x.get("play_addr") or {}
        u0 = (pa.get("url_list") or [None])[0]
        if not u0:
            continue
        gear_num = 0
        if x.get("gear_name"):
            m = re.search(r"(\d+)", str(x["gear_name"]))
            if m and int(m.group(1)) >= 144:
                gear_num = int(m.group(1))
        p = _eff_p(x.get("width") or 0, x.get("height") or 0, gear_num)
        if not p:
            continue
        size = x.get("data_size") or _est_size(p)
        key = str(p)
        prev = fmts.get(key)
        if not prev or size > prev["size"]:
            fmts[key] = {"label": "%dp" % p, "height": p,
                         "width": x.get("width") or 0, "size": size,
                         "fps": x.get("fps") or 0, "url": u0}
    # 默认 play_addr 通常是最高画质流，优先采用；size 缺失时沿用已有估算值
    pa = video.get("play_addr") or {}
    u0 = (pa.get("url_list") or [None])[0]
    if u0:
        p = _eff_p(pa.get("width") or 0, pa.get("height") or 0, 0)
        key = str(p) if p else "0"
        size = pa.get("data_size") or 0
        if not size:
            existing = fmts.get(key)
            size = existing["size"] if existing else _est_size(p)
        fmts[key] = {"label": ("%dp" % p) if p else "默认", "height": p,
                     "width": pa.get("width") or 0, "size": size,
                     "fps": 0, "url": u0}
    out = []
    for f in fmts.values():
        if "playwm" in f["url"]:
            f["url"] = f["url"].replace("playwm", "play")  # 无水印直链
        out.append(f)
    out.sort(key=lambda f: (f["height"] or 0, f["size"]), reverse=True)
    return out


def dy_resolve_video(url, log=None):
    """通过抖音官方 web API 解析视频（无需登录 Cookie、无需浏览器）。
    返回 (info, None) 或 (None, err)"""
    def _log(s):
        if log:
            log(s)
    vid = dy_extract_video_id(url)
    if not vid:
        return None, "无法从链接提取视频 ID（仅支持抖音视频链接）"
    _log("抖音视频 ID: %s" % vid)
    try:
        ttwid = dy_get_ttwid(log)
    except Exception as e:
        return None, "ttwid 获取失败：%s" % e
    api = ("https://www.douyin.com/aweme/v1/web/aweme/detail/"
           "?aweme_id=%s&aid=6383&channel=channel_pc_web&detail_list=1" % vid)
    try:
        req = urllib.request.Request(api, headers={
            "User-Agent": DY_UA,
            "Cookie": "ttwid=" + ttwid,
            "Referer": "https://www.douyin.com/",
            "Accept": "application/json",
            "Accept-Language": "zh-CN,zh;q=0.9",
        })
        with urllib.request.urlopen(req, timeout=25) as r:
            body = r.read()
        if not body:
            return None, "抖音 API 返回空（可能被反爬拦截）"
        d = json.loads(body.decode("utf-8", "ignore"))
    except Exception as e:
        return None, "抖音 API 请求失败：%s" % e
    det = d.get("aweme_detail")
    if not det:
        msg = ((d.get("filter_detail") or {}).get("detail_msg")) or ""
        return None, ("视频不可用：%s" % msg) if msg else "视频不可用（已删除或私密）"
    video = det.get("video") or {}
    formats = _dy_bitrate_to_formats(video)
    if not formats:
        return None, "未能解析到可播放的视频流"
    cover = (((video.get("cover") or {}).get("url_list")) or [None])[0] or ""
    return {
        "id": det.get("aweme_id") or vid,
        "title": (det.get("desc") or "").strip() or "douyin_video",
        "duration": int((video.get("duration") or 0) // 1000),
        "uploader": ((det.get("author") or {}).get("nickname")) or "",
        "thumbnail": cover,
        "formats": formats,
    }, None


def _dy_fmt_size(n):
    if not n:
        return ""
    if n >= 1024 ** 3:
        return "%.1f GB" % (n / 1024 ** 3)
    return "%.1f MB" % (n / 1024 ** 2)


def _dy_fmt_duration(sec):
    if not sec:
        return ""
    m, s = divmod(int(sec), 60)
    h, m = divmod(m, 60)
    return ("%d:%02d:%02d" % (h, m, s)) if h else ("%d:%02d" % (m, s))


def _dy_pick_format(info, quality):
    """按主界面画质设置从解析结果中选择流。
    返回 (fmt, audio_only)：
    - 仅音频 -> 最小码率流 + 提取音频
    - 最佳画质 -> 最高画质
    - 指定高度 -> 不超过该高度的最高画质；没有则取最小"""
    fmts = info["formats"]
    if quality == "仅音频":
        return fmts[-1], True
    cap = _QUALITY_HEIGHT.get(quality)
    if not cap:
        return fmts[0], False
    cands = [f for f in fmts if (f["height"] or 0) <= cap]
    return (cands[0] if cands else fmts[-1]), False


def _dy_parse_detail(body):
    """解析 aweme detail API 响应体，返回视频直链与标题"""
    try:
        d = (json.loads(body) or {}).get("aweme_detail") or {}
        play = (d.get("video") or {}).get("play_addr") or {}
        urls = play.get("url_list") or []
        if not urls:
            return None
        vurl = urls[0]
        if "playwm" in vurl:
            vurl = vurl.replace("playwm", "play")  # 无水印直链
        return {"url": vurl, "title": (d.get("desc") or "").strip()}
    except Exception:
        return None


def dy_grab_video_via_browser(browser, url, timeout=60, log=None):
    """借鉴“猫抓”思路：让真实浏览器打开视频页（浏览器 JS 原生完成全部反爬签名），
    拦截页面发出的网络请求，从 aweme detail API 响应或播放器视频请求中拿到视频直链与标题。
    新版 Chrome 已不再提供 HTTP /json/new 端点（返回 404），必须走浏览器级 WebSocket（DevToolsActivePort）
    新建标签页并附加，与 Cookie 流程共用同一条连接。
    返回 ({"url":..., "title":..., "kind":...}, None) 或 (None, 错误信息)"""
    def _log(s):
        if log:
            log(s)

    port, path = read_devtools_active_port(browser)
    if not port:
        return None, "未检测到浏览器调试端口（请在 chrome://inspect 开启 Remote debugging 并保持浏览器运行）"
    try:
        ws = _MiniWebSocket("ws://127.0.0.1:%d%s" % (port, path))
    except Exception as e:
        return None, "连接浏览器调试端口失败：%s（若浏览器弹出“允许远程调试？”，请点击允许后重试）" % e

    target_id = None
    try:
        def _wait_response(req_id, seconds=15):
            deadline = time.time() + seconds
            while time.time() < deadline:
                try:
                    msg = ws.recv(timeout=5)
                except Exception:
                    continue
                if not msg:
                    continue
                try:
                    obj = json.loads(msg)
                except Exception:
                    continue
                if obj.get("id") == req_id:
                    return obj
            return None

        # 1) 新建标签页：新版 Chrome 不再提供 HTTP /json/new 端点，必须走浏览器级 WebSocket
        ws.send({"id": 1, "method": "Target.createTarget", "params": {"url": url}})
        resp = _wait_response(1)
        if not resp:
            return None, "打开视频页失败：浏览器无响应"
        if "error" in resp:
            return None, "打开视频页失败：%s" % resp["error"].get("message", "")
        target_id = resp["result"].get("targetId")

        # 2) 附加到新标签页（flatten 会话，共用浏览器级连接，与 Cookie 流程同机制）
        ws.send({"id": 2, "method": "Target.attachToTarget",
                 "params": {"targetId": target_id, "flatten": True}})
        resp = _wait_response(2)
        if not resp:
            return None, "附加视频页失败（超时）"
        if "error" in resp:
            return None, "附加视频页失败：%s" % resp["error"].get("message", "")
        session_id = resp["result"].get("sessionId")

        def _send(obj):
            obj = dict(obj)
            obj["sessionId"] = session_id
            ws.send(obj)

        video_url = title = None
        detail_pending = False
        title_asked = False
        _send({"id": 3, "method": "Network.enable"})
        _log("已在浏览器中打开视频页，正在拦截网络请求 ...")
        deadline = time.time() + timeout
        while time.time() < deadline:
            try:
                msg = ws.recv(timeout=10)
            except Exception:
                continue
            if not msg:
                continue
            try:
                obj = json.loads(msg)
            except Exception:
                continue
            if obj.get("sessionId") != session_id:
                continue
            mid = obj.get("id")
            if obj.get("method") == "Network.responseReceived":
                params = obj.get("params", {})
                response = params.get("response", {})
                rurl = response.get("url", "")
                mime = (response.get("mimeType") or "").lower()
                if "aweme/v1/web/aweme/detail" in rurl and not detail_pending:
                    detail_pending = True
                    _send({"id": 4, "method": "Network.getResponseBody",
                           "params": {"requestId": params.get("requestId")}})
                elif video_url is None and (mime.startswith("video/") or ".mp4" in rurl
                                            or "playwm" in rurl or "video_id=" in rurl):
                    video_url = rurl
                    _log("已拦截到播放器视频请求")
            if mid == 4 and detail_pending:
                detail_pending = False
                info = _dy_parse_detail(obj.get("result", {}).get("body", ""))
                if info:
                    video_url = info["url"]
                    title = info["title"]
                    _log("已从 detail API 解析到视频信息")
            if mid == 5 and title is None:
                t = obj.get("result", {}).get("result", {}).get("value")
                if t:
                    title = str(t)
            if video_url and title:
                break
            if video_url and not title and not title_asked:
                title_asked = True
                _send({"id": 5, "method": "Runtime.evaluate",
                       "params": {"expression": "document.title"}})
        if not video_url:
            return None, "未拦截到视频请求（若视频没有自动播放，请在打开的浏览器页面里手动播放一次，再重试）"
        if title:
            title = re.sub(r"\s*[-\u2013\u2014]\s*抖音\s*$", "", title).strip()
        kind = "m3u8" if "m3u8" in video_url else "mp4"
        return {"url": video_url, "title": title or "douyin_video", "kind": kind}, None
    finally:
        try:
            if target_id:
                ws.send({"id": 99, "method": "Target.closeTarget", "params": {"targetId": target_id}})
        except Exception:
            pass
        try:
            ws.sock.close()
        except Exception:
            pass



# ============================ 新片场（xinpianchang.com） ============================
# 原理（2026-10-08 实测）：
#   1. 视频页 www.xinpianchang.com/a* 有 WAF JS 质询保护，纯 HTTP 一律 403/406
#      （yt-dlp 的 XinpianchangIE 已失效）；必须让真实浏览器标签页执行 JS 过验证。
#   2. 媒体 API（mod-api.xinpianchang.com）需要三样东西：
#      a) 页面 __NEXT_DATA__ 里的内部 vid —— 不是 URL 里的 /a<数字>，
#         直接拿数字 ID 调 API 会 404 record not found；
#      b) 页面内嵌的 appKey（站点级常量，以页面实时读取为准）；
#      c) 浏览器会话 Cookie —— 匿名请求整个 API 返回 404；未登录态下 4K 条目 url 为空。
#   3. 流程：浏览器开视频页（优先复用已打开的匹配标签页，免重复过 WAF）
#      -> 读 __NEXT_DATA__ 拿内部 vid/appKey -> 读会话 Cookie -> 调媒体 API 拿多画质直链。
def is_xinpianchang_url(url):
    return bool(re.search(r"xinpianchang\.com/a\d+", url, re.I))


XPC_UA = ("Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 "
          "(KHTML, like Gecko) Chrome/126.0.0.0 Safari/537.36")
XPC_REFERER = "https://www.xinpianchang.com/"
XPC_API = "https://mod-api.xinpianchang.com/mod/api/v2/media/%s?appKey=%s"


def xpc_extract_video_id(url):
    """URL 里的数字 ID（/a<数字>）；仅用于匹配浏览器已打开的标签页。
    调媒体 API 必须用页面 __NEXT_DATA__ 里的内部 vid。"""
    m = re.search(r"xinpianchang\.com/a(\d+)", url, re.I)
    return m.group(1) if m else None


def _xpc_wait_msg(ws, msg_id, session_id=None, timeout=15):
    """等待指定 CDP 响应（忽略事件消息；recv 超时不抛异常）"""
    deadline = time.time() + timeout
    while time.time() < deadline:
        try:
            msg = ws.recv(timeout=5)
        except Exception:
            continue
        if not msg:
            continue
        try:
            obj = json.loads(msg)
        except Exception:
            continue
        if obj.get("id") != msg_id:
            continue
        if session_id is not None and obj.get("sessionId") != session_id:
            continue
        return obj
    return None


def _xpc_read_next_data(ws, session_id, timeout):
    """轮询读取视频页 __NEXT_DATA__（等 WAF JS 验证 + 页面渲染完成）。
    返回 {"vid":..., "appKey":...} 或 None"""
    expr = ("(() => { try { const d = window.__NEXT_DATA__; "
            "if (!d) return null; "
            "const v = d.props.pageProps.detail.video; "
            "return JSON.stringify({vid: v.vid, appKey: v.appKey}); } "
            "catch (e) { return null; } })()")
    deadline = time.time() + timeout
    while time.time() < deadline:
        msg = {"id": 102, "method": "Runtime.evaluate",
               "params": {"expression": expr, "returnByValue": True}}
        if session_id is not None:
            msg["sessionId"] = session_id
        ws.send(msg)
        r = _xpc_wait_msg(ws, 102, session_id=session_id, timeout=10)
        if r and "result" in r:
            val = r["result"].get("result", {}).get("value")
            if val:
                try:
                    return json.loads(val)
                except Exception:
                    pass
        time.sleep(1.5)
    return None


def _xpc_session_cookies(ws, session_id):
    """读取新片场相关 Cookie，拼成 Cookie 请求头（无 Cookie 时返回空串）"""
    def _send(obj):
        if session_id is not None:
            obj = dict(obj)
            obj["sessionId"] = session_id
        ws.send(obj)
    _send({"id": 104, "method": "Network.enable"})
    _send({"id": 105, "method": "Network.getCookies",
           "params": {"urls": ["https://www.xinpianchang.com/",
                               "https://mod-api.xinpianchang.com/"]}})
    r = _xpc_wait_msg(ws, 105, session_id=session_id, timeout=15)
    if not r or "error" in r:
        return ""
    cookies = r["result"].get("cookies", [])
    return "; ".join("%s=%s" % (c.get("name", ""), c.get("value", ""))
                     for c in cookies if c.get("name"))


def _xpc_list_debug_pages():
    """经典调试端口（9222-9240）兜底：枚举所有页面标签。
    新版 Chrome 已移除 /json/new，经典端口无法新开标签页，只能复用已打开的。
    返回 [(target_id, url, page_ws_url), ...]"""
    for port in range(9222, 9241):
        try:
            with urllib.request.urlopen("http://127.0.0.1:%d/json/list" % port,
                                        timeout=2) as r:
                targets = json.loads(r.read().decode())
        except Exception:
            continue
        out = []
        for t in targets:
            if t.get("type") == "page" and t.get("webSocketDebuggerUrl"):
                out.append((t.get("id", ""), t.get("url", ""), t["webSocketDebuggerUrl"]))
        if out:
            return out
    return []


def xpc_resolve_video(browser, url, log=None):
    """解析新片场视频：浏览器开视频页读 __NEXT_DATA__（内部 vid/appKey）+ 会话 Cookie，
    再调媒体 API 拿多画质。返回 (info, None) 或 (None, err)"""
    def _log(s):
        if log:
            log(s)
    num_id = xpc_extract_video_id(url)
    if not num_id:
        return None, "无法从链接提取视频 ID（仅支持 xinpianchang.com/a<数字> 形式的视频链接）"
    _log("新片场链接 ID: %s" % num_id)
    data = None
    cookie_hdr = ""
    port, path = read_devtools_active_port(browser)
    if not port:
        # 经典调试端口兜底：只能复用已打开的匹配标签页
        match = None
        for _tid, u, ws_url in _xpc_list_debug_pages():
            if ("/a%s" % num_id) in u:
                match = ws_url
                break
        if not match:
            return None, ("请在浏览器里打开该视频页面后重试（保持标签页打开）：%s" % url)
        _log("✓ 找到已打开的匹配标签页（经典调试端口），直接读取")
        try:
            ws = _MiniWebSocket(match)
        except Exception as e:
            return None, "连接浏览器失败：%s" % e
        try:
            data = _xpc_read_next_data(ws, None, timeout=20)
            cookie_hdr = _xpc_session_cookies(ws, None)
        finally:
            try:
                ws.sock.close()
            except Exception:
                pass
    else:
        try:
            ws = _MiniWebSocket("ws://127.0.0.1:%d%s" % (port, path))
        except Exception as e:
            return None, ("连接浏览器调试端口失败：%s（若浏览器弹出“允许远程调试？”，请点击允许后重试）" % e)
        target_id = None
        close_after = False
        try:
            ws.send({"id": 100, "method": "Target.getTargets"})
            r = _xpc_wait_msg(ws, 100, timeout=15)
            pages = [t for t in (r or {}).get("result", {}).get("targetInfos", [])
                     if t.get("type") == "page"]
            for t in pages:
                if ("/a%s" % num_id) in (t.get("url") or ""):
                    target_id = t["targetId"]
                    break
            if target_id:
                _log("✓ 找到已打开的匹配标签页，直接读取（免重复 WAF 验证）")
            else:
                ws.send({"id": 101, "method": "Target.createTarget", "params": {"url": url}})
                r = _xpc_wait_msg(ws, 101, timeout=15)
                if not r or "error" in r:
                    return None, "打开视频页失败：%s" % (
                        (r or {}).get("error", {}).get("message", "超时"))
                target_id = r["result"]["targetId"]
                close_after = True
                _log("已在浏览器打开视频页，等待 WAF 验证与加载 ...")
            ws.send({"id": 106, "method": "Target.attachToTarget",
                     "params": {"targetId": target_id, "flatten": True}})
            r = _xpc_wait_msg(ws, 106, timeout=15)
            if not r or "error" in r:
                return None, "附加标签页失败：%s" % (
                    (r or {}).get("error", {}).get("message", "超时"))
            session_id = r["result"]["sessionId"]
            data = _xpc_read_next_data(ws, session_id,
                                       timeout=60 if close_after else 20)
            cookie_hdr = _xpc_session_cookies(ws, session_id)
        finally:
            try:
                if close_after and target_id:
                    ws.send({"id": 107, "method": "Target.closeTarget",
                             "params": {"targetId": target_id}})
                    time.sleep(0.3)
            except Exception:
                pass
            try:
                ws.sock.close()
            except Exception:
                pass
    if not data or not data.get("vid") or not data.get("appKey"):
        return None, ("未读到视频数据：WAF 可能弹出验证码。请在浏览器里手动打开该链接完成验证后重试"
                      "（保持标签页打开）：%s" % url)
    if not cookie_hdr:
        return None, "浏览器里没有找到新片场相关 Cookie：请先在浏览器里登录新片场账号后再重试"
    _log("✓ 已读取视频页数据（内部 vid=%s...，浏览器 Cookie %d 个，含登录态）"
         % (data["vid"][:8], len(cookie_hdr.split(";"))))
    api = XPC_API % (data["vid"], data["appKey"])
    headers = {"User-Agent": XPC_UA, "Referer": XPC_REFERER, "Accept": "application/json"}
    headers["Cookie"] = cookie_hdr
    try:
        req = urllib.request.Request(api, headers=headers)
        with urllib.request.urlopen(req, timeout=25) as r:
            d = json.loads(r.read().decode("utf-8", "ignore"))
    except Exception as e:
        code = getattr(e, "code", None)
        if code == 404:
            return None, "未找到该视频（已删除或设为私密），或浏览器会话态已失效（请在浏览器里重新打开新片场后再试）"
        return None, ("新片场媒体 API 请求失败：HTTP %s" % code) if code else ("新片场媒体 API 请求失败：%s" % e)
    d2 = (d or {}).get("data") or {}
    if not d2.get("resource"):
        return None, "视频不可用（已删除或私密），API 响应：%s" % (
            d.get("msg") or d.get("message") or "无数据")
    res = d2.get("resource") or {}
    fmts = []
    for prog in (res.get("progressive") or []):
        u = prog.get("url")
        if not u:
            continue  # 未登录态下 4K 条目的 url 为空，跳过
        # 档位号以网站 profile 命名（如“超清 2160p”）为准：视频可能是裁剪画幅，
        # 实际像素高度（如 1608）与档位命名（2160）不一致，选档要与用户认知一致
        m = re.search(r"(\d+)\s*p", str(prog.get("profile") or ""), re.I)
        tier = int(m.group(1)) if m else 0
        h = tier or (prog.get("height") or 0)
        fmts.append({
            "label": ("%dp" % h) if h else (prog.get("profile") or "mp4"),
            "height": h,
            "width": prog.get("width") or 0,
            "size": prog.get("filesize") or 0,
            "fps": 0,
            "url": u,
            "kind": "mp4",
        })
    hls = (res.get("hls") or {}).get("url")
    if hls:
        fmts.append({"label": "HLS", "height": 0, "width": 0, "size": 0,
                     "fps": 0, "url": hls, "kind": "hls"})
    dash = (res.get("dash") or {}).get("url")
    if dash:
        fmts.append({"label": "DASH", "height": 0, "width": 0, "size": 0,
                     "fps": 0, "url": dash, "kind": "dash"})
    if not fmts:
        return None, "媒体 API 未返回任何可下载的视频流"
    fmts.sort(key=lambda f: (f["height"] or 0, f["size"]), reverse=True)
    up = d2.get("owner") or d2.get("uploader")
    uploader = up.get("name") if isinstance(up, dict) else (str(up) if up else "")
    cover = d2.get("cover") or ""
    if isinstance(cover, dict):
        cover = cover.get("url") or ""
    return {
        "id": data["vid"],
        "title": (d2.get("title") or "").strip() or "xinpianchang_video",
        "duration": int(d2.get("duration") or 0),
        "uploader": uploader,
        "thumbnail": cover,
        "cookie": cookie_hdr,
        "formats": fmts,
    }, None


def _xpc_pick_format(info, quality):
    """按主界面画质设置从解析结果中选择流（与抖音同规则）。
    返回 (fmt, audio_only)：
    - 仅音频 -> 最小画质流 + 提取音频
    - 最佳画质 -> 最高画质
    - 指定高度 -> 不超过该高度的最高画质；没有则取最小"""
    fmts = info["formats"]
    if quality == "仅音频":
        return fmts[-1], True
    cap = _QUALITY_HEIGHT.get(quality)
    if not cap:
        return fmts[0], False
    cands = [f for f in fmts if (f["height"] or 0) <= cap]
    return (cands[0] if cands else fmts[-1]), False


