def get_local_deno_version():
    exe = app_dir() / "deno.exe"
    if not exe.exists():
        return None
    try:
        out = subprocess.run([str(exe), "--version"], capture_output=True, text=True, timeout=30,
                             creationflags=getattr(subprocess, "CREATE_NO_WINDOW", 0)).stdout
        m = re.search(r"deno\s+([\d.]+)", out)
        return m.group(1) if m else None
    except Exception:
        return None


def compare_versions(local, latest):
    """最新版 > 本地版 则返回 True（需要更新）"""
    if not local or not latest:
        return False

    def nums(v):
        return [int(x) for x in re.findall(r"\d+", v)][:4] or [0]

    return nums(latest) > nums(local)


def download_deno(version, log=None):
    """下载最新版 deno 并替换本目录的 deno.exe"""
    def out(msg):
        if log:
            try:
                out(msg)
            except Exception:
                pass

    url = "https://github.com/denoland/deno/releases/download/v%s/deno-x86_64-pc-windows-msvc.zip" % version
    dest = app_dir() / "deno.exe"
    tmp_zip = app_dir() / "deno_update.zip"
    tmp_dir = app_dir() / ".deno_tmp"
    try:
        out("正在下载 deno %s ..." % version)
        req = urllib.request.Request(url, headers={"User-Agent": "Mozilla/5.0 yt-dlp-gui"})
        with urllib.request.urlopen(req, timeout=180) as r:
            total = int(r.headers.get("Content-Length") or 0)
            done = 0
            with open(tmp_zip, "wb") as f:
                while True:
                    chunk = r.read(65536)
                    if not chunk:
                        break
                    f.write(chunk)
                    done += len(chunk)
                    if total and log and done % (2 * 1024 * 1024) < 65536:
                        out("下载中 ... %d%%" % (done * 100 // total))
        out("下载完成，正在解压 ...")
        tmp_dir.mkdir(exist_ok=True)
        with zipfile.ZipFile(tmp_zip) as z:
            names = z.namelist()
            entry = "deno.exe" if "deno.exe" in names else next((n for n in names if n.endswith("deno.exe")), None)
            if not entry:
                raise RuntimeError("压缩包里没有 deno.exe")
            z.extract(entry, tmp_dir)
        extracted = tmp_dir / os.path.basename(entry)
        if dest.exists():
            dest.unlink()
        shutil.copy2(extracted, dest)
        out("✓ deno 已更新到 %s" % version)
        return True, version
    except Exception as e:
        out("✗ deno 更新失败：%s" % e)
        return False, str(e)
    finally:
        try:
            tmp_zip.unlink(missing_ok=True)
            shutil.rmtree(tmp_dir, ignore_errors=True)
        except Exception:
            pass



# =============================================================================
# 微信视频号下载支持
#
# 复用成熟开源方案 ltaoo/wx_channels_download（MIT License + Commons Clause）。
# 该引擎以本地服务方式运行：通过系统代理拦截微信视频号页面并注入下载入口，
# 同时在本地暴露 REST API。本软件只负责：下载/更新引擎、启动/停止服务、
# 把视频号分享链接提交给引擎下载、展示引擎的下载任务进度。
# 引擎源码与说明：https://github.com/ltaoo/wx_channels_download
# =============================================================================

WXCHANNELS_REPO = "ltaoo/wx_channels_download"
WXCHANNELS_ENGINE_DIRNAME = "wxchannels_engine"
WXCHANNELS_ENGINE_EXE = "wx_video_download.exe"
WXCHANNELS_API_HOST = "127.0.0.1"
WXCHANNELS_API_PORT = 2022
WXCHANNELS_PROXY_PORT = 2023
WXCHANNELS_PANEL_URL = "http://127.0.0.1:2022/"
WXCHANNELS_EXISTING_ACTIONS = ["skip", "overwrite", "duplicate", "error"]
WXCHANNELS_SHARE_RE = re.compile(
    r"^https?://(?:weixin\.qq\.com/sph/|channels\.weixin\.qq\.com/)", re.I)
WXCHANNELS_TASK_STATUS = {
    0: "等待中", 1: "准备中", 2: "下载中", 3: "已暂停",
    4: "合并中", 5: "已完成", 6: "失败", 7: "已取消",
}


def wxchannels_engine_dir() -> Path:
    return app_dir() / WXCHANNELS_ENGINE_DIRNAME


def wxchannels_engine_exe() -> Path:
    return wxchannels_engine_dir() / WXCHANNELS_ENGINE_EXE


def wxchannels_engine_installed() -> bool:
    return wxchannels_engine_exe().exists()


def is_wxchannels_url(url: str) -> bool:
    """判断是否为微信视频号链接（sph 短链或视频号页面链接）"""
    return bool(url) and bool(WXCHANNELS_SHARE_RE.match(url.strip()))


def split_wxchannels_urls(urls):
    """把链接分成（视频号链接, 其他链接）两组，保持原顺序"""
    wx, other = [], []
    for u in urls:
        (wx if is_wxchannels_url(u) else other).append(u)
    return wx, other


def wxchannels_api_call(path, method="GET", body=None, timeout=15, base=None):
    """调用视频号引擎的本地 REST API，返回 (数据, 错误)"""
    base = base or ("http://%s:%d" % (WXCHANNELS_API_HOST, WXCHANNELS_API_PORT))
    url = base.rstrip("/") + path
    data = None
    headers = {"Accept": "application/json", "User-Agent": "ytdlp-gui"}
    if body is not None:
        data = json.dumps(body, ensure_ascii=False).encode("utf-8")
        headers["Content-Type"] = "application/json"
    req = urllib.request.Request(url, data=data, headers=headers, method=method)
    # 引擎在本机，必须绕过系统代理（引擎自身也会设置系统代理）
    opener = urllib.request.build_opener(urllib.request.ProxyHandler({}))
    try:
        with opener.open(req, timeout=timeout) as r:
            raw = r.read().decode("utf-8", "replace")
    except Exception as e:
        return None, "无法连接视频号服务：%s" % e
    if not raw.strip():
        return None, "视频号服务返回了空响应"
    try:
        payload = json.loads(raw)
    except Exception:
        return None, "视频号服务返回了无法解析的内容：%s" % raw[:200]
    if isinstance(payload, dict) and payload.get("code") not in (None, 0):
        return None, str(payload.get("msg") or payload.get("error") or "视频号服务返回错误")
    if isinstance(payload, dict) and "data" in payload:
        return payload["data"], None
    return payload, None


def wxchannels_api_alive(timeout=3) -> bool:
    data, err = wxchannels_api_call(
        "/api/v1/download_task/list?page=1&page_size=1", timeout=timeout)
    return err is None and isinstance(data, dict)


