def _wxchannels_asset_suffix() -> str:
    machine = (os.environ.get("PROCESSOR_ARCHITECTURE") or "").upper()
    if machine == "ARM64":
        return "windows_arm64"
    return "windows_x86_64"


def install_wxchannels_engine(log=None):
    """从 GitHub 下载并解压视频号引擎到本目录（首次使用与更新都走这里）"""
    def out(msg):
        if log:
            try:
                log(msg)
            except Exception:
                pass

    latest = get_latest_version(WXCHANNELS_REPO)
    if not latest:
        return False, "无法获取视频号引擎最新版本（请检查网络）"
    suffix = _wxchannels_asset_suffix()
    names = [
        "wx_video_download_v%s_%s.zip" % (latest, suffix),
        "wx_video_download_safe_v%s_%s.zip" % (latest, suffix),
    ]
    dest_dir = wxchannels_engine_dir()
    tmp_zip = app_dir() / "wxchannels_engine_update.zip"
    tmp_dir = app_dir() / ".wxchannels_engine_tmp"
    last_err = None
    for name in names:
        url = "https://github.com/%s/releases/download/v%s/%s" % (
            WXCHANNELS_REPO, latest, name)
        try:
            out("正在下载视频号引擎 %s ..." % latest)
            req = urllib.request.Request(
                url, headers={"User-Agent": "Mozilla/5.0 ytdlp-gui"})
            with urllib.request.urlopen(req, timeout=300) as r, open(tmp_zip, "wb") as f:
                shutil.copyfileobj(r, f, 1024 * 256)
            out("下载完成，正在解压 ...")
            shutil.rmtree(tmp_dir, ignore_errors=True)
            tmp_dir.mkdir(parents=True, exist_ok=True)
            with zipfile.ZipFile(tmp_zip) as z:
                z.extractall(tmp_dir)
            entry = None
            for root, _dirs, files in os.walk(tmp_dir):
                if WXCHANNELS_ENGINE_EXE in files:
                    entry = Path(root) / WXCHANNELS_ENGINE_EXE
                    break
            if entry is None:
                raise RuntimeError("压缩包里没有 %s" % WXCHANNELS_ENGINE_EXE)
            dest_dir.mkdir(parents=True, exist_ok=True)
            for item in entry.parent.iterdir():
                target = dest_dir / item.name
                if item.is_dir():
                    shutil.copytree(item, target, dirs_exist_ok=True)
                else:
                    shutil.copy2(item, target)
            out("✓ 视频号引擎已就绪（%s）" % latest)
            return True, latest
        except Exception as e:
            last_err = e
            out("尝试 %s 失败：%s" % (name, e))
        finally:
            try:
                tmp_zip.unlink(missing_ok=True)
            except Exception:
                pass
            shutil.rmtree(tmp_dir, ignore_errors=True)
    return False, "视频号引擎下载失败：%s" % last_err


def ensure_wxchannels_engine(log=None):
    """确保引擎已安装（未安装则自动下载）"""
    if wxchannels_engine_installed():
        return True, None
    ok, msg = install_wxchannels_engine(log=log)
    return ok, (None if ok else msg)


def wxchannels_engine_config_path() -> Path:
    return wxchannels_engine_dir() / "config.yaml"


WXCHANNELS_PROXY_REGS = (
    ("ProxyEnable", "dword"),
    ("ProxyServer", "sz"),
    ("ProxyOverride", "sz"),
    ("AutoConfigURL", "sz"),
)


def _wxchannels_reg_path():
    return r"Software\Microsoft\Windows\CurrentVersion\Internet Settings"


def _winreg():
    import winreg
    return winreg


def wxchannels_capture_system_proxy():
    """读取当前系统代理设置，供引擎退出后还原。

    引擎停止时用的是 DisableProxyIfMatches，它会直接把 ProxyEnable 置 0，
    也就是把用户自己的代理一起关掉（例如用户的 127.0.0.1:7897）。
    所以本程序必须自己备份、自己还原。
    """
    if os.name != "nt":
        return None
    winreg = _winreg()
    snap = {}
    try:
        with winreg.OpenKey(winreg.HKEY_CURRENT_USER, _wxchannels_reg_path()) as key:
            for name, _kind in WXCHANNELS_PROXY_REGS:
                try:
                    snap[name] = winreg.QueryValueEx(key, name)[0]
                except FileNotFoundError:
                    pass
    except OSError:
        return None
    return snap or None


def wxchannels_restore_system_proxy(snapshot) -> bool:
    """把系统代理还原成快照内容，并通知系统刷新。"""
    if os.name != "nt" or not snapshot:
        return False
    winreg = _winreg()
    kinds = {"dword": winreg.REG_DWORD, "sz": winreg.REG_SZ}
    try:
        with winreg.OpenKey(winreg.HKEY_CURRENT_USER, _wxchannels_reg_path(), 0,
                            winreg.KEY_SET_VALUE) as key:
            for name, kind in WXCHANNELS_PROXY_REGS:
                if name not in snapshot:
                    continue
                value = snapshot[name]
                if kind == "dword":
                    value = int(value)
                else:
                    value = str(value)
                winreg.SetValueEx(key, name, 0, kinds[kind], value)
    except OSError:
        return False
    try:
        wininet = ctypes.windll.wininet
        for option in (39, 37):
            wininet.InternetSetOptionW(0, option, 0, 0)
    except Exception:
        pass
    return True


def wxchannels_system_proxy_matches(snapshot) -> bool:
    """检查系统代理是否已经等于快照（用于确认还原成功）。"""
    if os.name != "nt":
        return True
    current = wxchannels_capture_system_proxy()
    if current is None or snapshot is None:
        return current == snapshot
    for name, _kind in WXCHANNELS_PROXY_REGS:
        left = current.get(name)
        right = snapshot.get(name)
        if name == "ProxyEnable":
            left = int(left) if left is not None else None
            right = int(right) if right is not None else None
        if left != right:
            return False
    return True


WXCHANNELS_PROXY_BACKUP_NAME = "proxy_backup.json"


def wxchannels_proxy_backup_path() -> Path:
    return wxchannels_engine_dir() / WXCHANNELS_PROXY_BACKUP_NAME


def wxchannels_save_proxy_backup() -> bool:
    """启动引擎前备份系统代理。

    只在没有备份文件时写入，保证保存的一定是用户原始设置（而不是被引擎改过的值）。
    """
    if os.name != "nt":
        return False
    path = wxchannels_proxy_backup_path()
    if path.exists():
        return True
    snapshot = wxchannels_capture_system_proxy()
    if snapshot is None:
        return False
    wxchannels_engine_dir().mkdir(parents=True, exist_ok=True)
    path.write_text(json.dumps(snapshot, ensure_ascii=False, indent=2), encoding="utf-8")
    return True


def wxchannels_load_proxy_backup():
    path = wxchannels_proxy_backup_path()
    if not path.exists():
        return None
    try:
        return json.loads(path.read_text(encoding="utf-8"))
    except Exception:
        return None


def wxchannels_discard_proxy_backup():
    try:
        wxchannels_proxy_backup_path().unlink(missing_ok=True)
    except Exception:
        pass


def wxchannels_restore_proxy_from_backup() -> bool:
    """把系统代理还原成备份内容（引擎无论怎么退出都能救回网络）。"""
    snapshot = wxchannels_load_proxy_backup()
    if snapshot is None:
        return False
    ok = wxchannels_restore_system_proxy(snapshot)
    if ok or wxchannels_system_proxy_matches(snapshot):
        wxchannels_discard_proxy_backup()
        return True
    return False


def wxchannels_recover_system_proxy(log=None) -> bool:
    """崩溃恢复：有备份、且引擎没在跑时，把系统代理还原回去。

    引擎正常模式不会写 pid 文件，进程被强杀时代理会残留指向 127.0.0.1:2023，
    此时整机网络都会断。启动时调用本函数即可自愈。
    """
    def out(msg):
        if log:
            try:
                log(msg)
            except Exception:
                pass

    if not wxchannels_load_proxy_backup():
        return False
    if wxchannels_api_alive(timeout=2):
        return False
    out("检测到上次视频号服务退出时未还原系统代理，正在还原 ...")
    ok = wxchannels_restore_proxy_from_backup()
    out("✓ 系统代理已还原" if ok else "✗ 系统代理还原失败，请在系统设置里检查代理")
    return ok


def write_wxchannels_engine_config(download_dir: str, keep_system_proxy: bool = True):
    """生成引擎配置。

    键名使用引擎自己序列化时的全小写形式，避免大小写歧义；
    同时不写 inject.globalScript / download.hooksScript，免得引擎报脚本缺失。
    proxy.system 决定引擎启动时是否接管系统代理；代理的备份与还原由本程序负责。
    """
    cfg = (
        "# 由 XX Down 自动生成，请勿手工修改（会被覆盖）\n"
        "download:\n"
        "    dir: %s\n"
        "    defaultactionwhenexisting: skip\n"
        "    playdoneaudio: false\n"
        "api:\n"
        "    protocol: http\n"
        "    hostname: 127.0.0.1\n"
        "    port: %d\n"
        "mcp:\n"
        "    enabled: false\n"
        "proxy:\n"
        "    enabled: true\n"
        "    system: %s\n"
        "    hostname: 127.0.0.1\n"
        "    port: %d\n"
        "    skipinstallrootcert: false\n"
        "channels:\n"
        "    download:\n"
        "        defaulthighest: true\n"
        "        cover: false\n"
    ) % (download_dir.replace("\\", "/"),
         WXCHANNELS_API_PORT,
         "true" if keep_system_proxy else "false",
         WXCHANNELS_PROXY_PORT)
    wxchannels_engine_dir().mkdir(parents=True, exist_ok=True)
    wxchannels_engine_config_path().write_text(cfg, encoding="utf-8")


def _wxchannels_child_env():
    r"""构造引擎子进程的环境变量。

    引擎在 Windows 上用 `powershell.exe` 枚举根证书来判断 SunnyNet 证书是否已安装。
    如果父进程的 PSModulePath 里存在 PowerShell 7 的模块目录（例如从 pwsh / 某些
    编辑器 / Agent 运行时中启动本程序），Windows PowerShell 5.1 会优先加载 PS7 版
    Microsoft.PowerShell.Security，该版本不注册 Certificate provider，于是
    `Get-ChildItem Cert:\LocalMachine\Root` 报 “Cannot find drive. A drive with the
    name 'Cert' does not exist.”，引擎随后以 “failed to check certificate” 退出。
    这里显式给子进程一个只含系统 Windows PowerShell 模块路径的 PSModulePath，
    避免父进程环境污染引擎。
    """
    env = os.environ.copy()
    machine = os.environ.get("ProgramFiles", r"C:\Program Files")
    win_root = os.environ.get("SystemRoot", r"C:\WINDOWS")
    env["PSModulePath"] = ";".join([
        os.path.join(machine, "WindowsPowerShell", "Modules"),
        os.path.join(win_root, "system32", "WindowsPowerShell", "v1.0", "Modules"),
    ])
    # 引擎做后处理（音视频合并）时会直接调用 ffmpeg，把软件自带的 ffmpeg 目录加到 PATH。
    tools = str(app_dir())
    existing_path = env.get("PATH", "")
    if tools not in existing_path.split(os.pathsep):
        env["PATH"] = tools + os.pathsep + existing_path
    return env


def _wxchannels_no_window_flag():
    if os.name != "nt":
        return 0
    return subprocess.CREATE_NEW_PROCESS_GROUP | getattr(subprocess, "CREATE_NO_WINDOW", 0)


def wxchannels_engine_running_pids():
    """列出所有在跑的视频号引擎进程号（引擎自身不带可用的 pid 文件）。"""
    if os.name != "nt":
        return []
    try:
        out = subprocess.run(
            ["tasklist", "/FI", "IMAGENAME eq %s" % WXCHANNELS_ENGINE_EXE, "/FO", "CSV", "/NH"],
            capture_output=True, timeout=20,
            creationflags=getattr(subprocess, "CREATE_NO_WINDOW", 0)).stdout
    except Exception:
        return []
    pids = []
    for line in (out or b"").decode("utf-8", "replace").splitlines():
        line = line.strip()
        if not line.startswith('"'):
            continue
        parts = [c.strip().strip('"') for c in line.split('","')]
        if len(parts) < 2:
            continue
        try:
            pids.append(int(parts[1]))
        except ValueError:
            continue
    return pids


def start_wxchannels_engine(download_dir: str, keep_system_proxy: bool = True, log=None):
    """启动视频号引擎。

    以引擎的“正常模式”（根命令）启动：它会安装根证书、启动本地 API，并在
    proxy.system 为 true 时接管系统代理以拦截视频号页面。

    代理的备份/还原由本程序负责：引擎退出时只做 DisableProxyIfMatches，
    会把用户自己的代理一起关掉，所以不能依赖它还原。
    """
    def out(msg):
        if log:
            try:
                log(msg)
            except Exception:
                pass

    if not wxchannels_engine_installed():
        return False, "视频号引擎尚未安装"
    if wxchannels_api_alive(timeout=2):
        return True, "already"

    # 引擎自带的 pid 文件在中文 Windows 上会被误判为“进程仍在运行”，导致服务再也起不来。
    try:
        (wxchannels_engine_dir() / "wx_video_download.pid").unlink(missing_ok=True)
    except Exception:
        pass

    if keep_system_proxy and not wxchannels_save_proxy_backup():
        return False, "无法备份当前系统代理设置"

    write_wxchannels_engine_config(download_dir, keep_system_proxy=keep_system_proxy)

    exe = wxchannels_engine_exe()
    args = [str(exe), "--workdir", str(wxchannels_engine_dir()),
            "--config", str(wxchannels_engine_config_path())]
    if keep_system_proxy:
        out("正在启动视频号服务（会接管系统代理，如弹出系统授权提示请选择“是”）...")
    else:
        out("正在启动视频号服务（不接管系统代理）...")
    try:
        subprocess.Popen(args, cwd=str(wxchannels_engine_dir()),
                         creationflags=_wxchannels_no_window_flag(),
                         env=_wxchannels_child_env(),
                         stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL,
                         stdin=subprocess.DEVNULL)
    except Exception as e:
        return False, "启动视频号服务失败：%s" % e

    deadline = time.time() + 60
    while time.time() < deadline:
        if wxchannels_api_alive(timeout=2):
            return True, None
        time.sleep(1)
    return False, "视频号服务启动超时（可能未授权系统代理）"


def stop_wxchannels_engine(log=None):
    """停止视频号引擎，并还原系统代理。

    不能调用引擎的 `server stop`：正常模式没有 pid 文件，stop 找不到进程。
    这里直接结束引擎进程，再用启动前的备份还原系统代理。
    """
    def out(msg):
        if log:
            try:
                log(msg)
            except Exception:
                pass

    flags = getattr(subprocess, "CREATE_NO_WINDOW", 0)
    killed = []
    for pid in wxchannels_engine_running_pids():
        try:
            subprocess.run(["taskkill", "/F", "/T", "/PID", str(pid)],
                           capture_output=True, timeout=30, creationflags=flags)
        except Exception:
            pass
        killed.append(pid)
    for pid in wxchannels_engine_running_pids():
        try:
            subprocess.run(["taskkill", "/F", "/T", "/IM", WXCHANNELS_ENGINE_EXE],
                           capture_output=True, timeout=30, creationflags=flags)
        except Exception:
            pass
        break

    deadline = time.time() + 20
    while time.time() < deadline:
        if not wxchannels_api_alive(timeout=2) and not wxchannels_engine_running_pids():
            break
        time.sleep(0.5)

    stopped = not wxchannels_api_alive(timeout=2)
    if wxchannels_load_proxy_backup():
        out("正在还原系统代理 ...")
        if wxchannels_restore_proxy_from_backup():
            out("✓ 系统代理已还原")
        else:
            out("✗ 系统代理还原失败，请在系统设置里检查代理")
    if not stopped:
        out("✗ 视频号服务未能完全退出，建议在任务管理器里结束 %s" % WXCHANNELS_ENGINE_EXE)
    return stopped


def wxchannels_list_tasks(page_size=50):
    data, err = wxchannels_api_call(
        "/api/v1/download_task/list?page=1&page_size=%d" % page_size, timeout=15)
    if err:
        return None, err
    tasks = (data or {}).get("list") or []
    return tasks, None


def wxchannels_channels_status():
    """查询引擎是否已连接微信视频号页面（返回 (available, 说明)）。"""
    data, err = wxchannels_api_call("/api/channels/status", timeout=10)
    if err:
        return None, err
    if not isinstance(data, dict):
        return None, "视频号服务返回了无法识别的内容"
    return bool(data.get("available")), None


def wxchannels_sph_status():
    """查询“视频号分享链接”这条通道是否可用（需要 yuanbao cookie 或已连接页面）。"""
    data, err = wxchannels_api_call("/api/scraper/platform/status", timeout=15)
    if err:
        return None, err
    for item in (data or {}).get("statuses") or []:
        if item.get("key") == "wxchannels:sph":
            return bool(item.get("available")), item.get("reason")
    return None, None


def wxchannels_fetch(url, log=None, timeout=180):
    """让引擎抓取链接元数据（视频号需微信视频号页面已连接，或已配置 yuanbao cookie）。

    返回 (抓取结果输出, 错误)。输出里含 result / download_info，可直接用于创建下载任务。
    """
    def out(msg):
        if log:
            try:
                log(msg)
            except Exception:
                pass

    # 视频号分享链接只有两条可用路径：已连接视频号页面，或已配置 yuanbao.tencent.com Cookie。
    # 两者都没有时引擎会直接拒绝，提前给出可操作的提示，避免用户干等超时。
    if is_wxchannels_url(url):
        page_ok, perr = wxchannels_channels_status()
        if perr:
            return None, perr
        if not page_ok:
            sph_ok, reason = wxchannels_sph_status()
            if sph_ok:
                pass
            else:
                return None, (
                    "视频号链接暂时无法解析：请先点“启动服务”，再在微信 PC 端打开“视频号”，"
                    "把视频号双击分离成独立窗口后播放任意视频（让引擎接管页面），"
                    "然后回到本软件重试。"
                    + ("（%s）" % reason if reason else ""))

    job, err = wxchannels_api_call(
        "/api/scraper/fetch", method="POST", body={"url": url}, timeout=30)
    if err:
        return None, err
    job_id = (job or {}).get("id")
    if not job_id:
        return None, "视频号服务未返回抓取任务编号"
    out("已提交解析任务（%s），等待引擎解析 ..." % job_id)
    deadline = time.time() + timeout
    last_stage = None
    while time.time() < deadline:
        time.sleep(2)
        status, serr = wxchannels_api_call(
            "/api/scraper/job?id=%s" % job_id, timeout=20)
        if serr:
            return None, serr
        state = (status or {}).get("status")
        progress = (status or {}).get("progress") or {}
        stage = progress.get("message")
        if stage and stage != last_stage:
            out("  " + str(stage))
            last_stage = stage
        if state in ("completed", "failed", "interrupted"):
            if state != "completed":
                return None, (status or {}).get("error") or "解析失败（%s）" % state
            output = (status or {}).get("output") or {}
            if output.get("result") is None:
                return None, "解析结果为空"
            return output, None
    return None, "解析超时（%d 秒）；视频号链接需要先打开微信视频号页面" % timeout


def wxchannels_create_task(url, download_dir=None, filename=None, existing_action="skip", log=None):
    """在引擎里创建下载任务，返回 (任务, 错误)。

    必须走引擎自己的 scraper -> create 管线。原因有两个：
    1. 视频号分享链接是页面地址而不是媒体直链，交给 create_by_url 会被当成普通文件下载，
       报 "resource unique ID is required"；
    2. 引擎 v260907 的 create_by_url 建资源时不写 UniqueID，直链下载路径本身就是坏的。
    """

    output, err = wxchannels_fetch(url, log=log)
    if err:
        return None, err
    config = {"existing_action": existing_action}
    if filename:
        config["filename"] = filename
    body = {"objects": [{
        "platform": output.get("platform"),
        "content": output.get("result"),
        "build_from_fetch": bool(output.get("download_info")),
        "config": config,
        "auto_start": True,
    }]}
    if download_dir:
        body["objects"][0]["download_dir"] = download_dir
    data, cerr = wxchannels_api_call(
        "/api/v1/download_task/create", method="POST", body=body, timeout=120)
    if cerr:
        return None, cerr
    items = (data or {}).get("tasks") or []
    if not items:
        return None, "视频号服务未返回任务结果"
    item = items[0]
    if item.get("code") not in (None, 0):
        return None, str(item.get("msg") or "创建视频号下载任务失败")
    task = item.get("data") or {}
    return task, None


