def _svg_icon(name, color=ACCENT, size=20, width=1.9):
    path = ICON_PATHS.get(name, "")
    svg = (
        '<svg xmlns="http://www.w3.org/2000/svg" width="24" height="24" viewBox="0 0 24 24" '
        'fill="none" stroke="%s" stroke-width="%s" stroke-linecap="round" stroke-linejoin="round">'
        '<path d="%s"/></svg>' % (color, width, path)
    )
    renderer = QtSvg.QSvgRenderer(QtCore.QByteArray(svg.encode("utf-8")))
    pm = QtGui.QPixmap(size, size)
    pm.fill(QtCore.Qt.transparent)
    painter = QtGui.QPainter(pm)
    renderer.render(painter)
    painter.end()
    return QtGui.QIcon(pm)


def _svg_pixmap(name, color=ACCENT, size=20, width=1.9):
    return _svg_icon(name, color, size, width).pixmap(size, size)


