def _set_taskbar_icon(hwnd):
    """设置窗口类图标：经 pythonw 启动时任务栏默认显示 Python 图标，这里换成应用 Logo"""
    try:
        import ctypes
        import tempfile
        tmp = os.path.join(tempfile.gettempdir(), "xxdown_taskbar_icon.ico")
        _logo_pixmap().save(tmp, "ICO", [16, 24, 32, 48, 64, 256])
        user32 = ctypes.windll.user32
        user32.LoadImageW.restype = ctypes.c_void_p
        user32.SetClassLongPtrW.argtypes = [ctypes.c_void_p, ctypes.c_int, ctypes.c_void_p]
        user32.SetClassLongPtrW.restype = ctypes.c_void_p
        h_icon = user32.LoadImageW(None, tmp, 1, 0, 0, 0)
        if h_icon:
            user32.SetClassLongPtrW(hwnd, -12, h_icon)
            user32.SetClassLongPtrW(hwnd, -14, h_icon)
    except Exception:
        pass


