# =============== 兼容旧逻辑的变量适配器 ===============
class _TextVar:
    def __init__(self, widget):
        self.w = widget

    def get(self):
        return self.w.text()

    def set(self, value):
        self.w.setText("" if value is None else str(value))


class _ComboVar:
    def __init__(self, widget):
        self.w = widget

    def get(self):
        return self.w.currentText()

    def set(self, value):
        idx = self.w.findText(str(value))
        if idx >= 0:
            self.w.setCurrentIndex(idx)


class _CheckVar:
    def __init__(self, widget):
        self.w = widget

    def get(self):
        return self.w.isChecked()

    def set(self, value):
        self.w.setChecked(bool(value))


class _RadioVar:
    """单选组：保留 StringVar 的 get/set 语义"""

    def __init__(self, buttons, default):
        self.buttons = buttons
        self.default = default

    def get(self):
        for value, btn in self.buttons.items():
            if btn.isChecked():
                return value
        return self.default

    def set(self, value):
        btn = self.buttons.get(value) or self.buttons.get(self.default)
        if btn is not None:
            btn.setChecked(True)


class _Dispatcher(QtCore.QObject):
    """把工作线程的回调安全地投递到 GUI 线程"""

    call = QtCore.Signal(object, tuple)

    def __init__(self):
        super().__init__()
        self.call.connect(self._run)

    @QtCore.Slot(object, tuple)
    def _run(self, fn, args):
        try:
            fn(*args)
        except Exception:
            pass


# ============================ 通用组件 ============================
def _shadow(widget, blur=34, dy=8, alpha=26, color=(60, 70, 110)):
    eff = QtWidgets.QGraphicsDropShadowEffect(widget)
    eff.setBlurRadius(blur)
    eff.setXOffset(0)
    eff.setYOffset(dy)
    eff.setColor(QtGui.QColor(color[0], color[1], color[2], alpha))
    widget.setGraphicsEffect(eff)
    return eff


class Card(QtWidgets.QFrame):
    """白色圆角卡片 + 柔和阴影"""

    def __init__(self, parent=None, radius=16, padding=18, spacing=12, shadow=True):
        super().__init__(parent)
        self.setObjectName("card")
        self.setStyleSheet("#card{background:%s;border-radius:%dpx;}" % (CARD, radius))
        self._lay = QtWidgets.QVBoxLayout(self)
        self._lay.setContentsMargins(padding, padding, padding, padding)
        self._lay.setSpacing(spacing)
        if shadow:
            _shadow(self, blur=30, dy=7, alpha=22)
        self.body = self._lay

    def add(self, widget, stretch=0):
        self._lay.addWidget(widget, stretch)
        return widget

    def add_layout(self, layout):
        self._lay.addLayout(layout)
        return layout


class SectionTitle(QtWidgets.QWidget):
    """卡片标题：小图标 + 标题 + 说明"""

    def __init__(self, text, icon=None, subtitle=None, parent=None, inline=False):
        super().__init__(parent)
        row = QtWidgets.QHBoxLayout(self)
        row.setContentsMargins(0, 0, 0, 0)
        row.setSpacing(9)
        if icon:
            lab = QtWidgets.QLabel()
            lab.setPixmap(_svg_pixmap(icon, ACCENT, 18))
            lab.setFixedSize(20, 20)
            row.addWidget(lab)
        box = QtWidgets.QVBoxLayout()
        box.setContentsMargins(0, 0, 0, 0)
        box.setSpacing(1)
        title = QtWidgets.QLabel(text)
        title.setStyleSheet("color:%s;font-size:14px;font-weight:600;" % TEXT)
        box.addWidget(title)
        if subtitle:
            sub = QtWidgets.QLabel(subtitle)
            sub.setStyleSheet("color:%s;font-size:11px;" % MUTED)
            if inline:
                row.addLayout(box)
                row.addWidget(sub)
                row.addStretch(1)
                return
            box.addWidget(sub)
        row.addLayout(box)
