class RoundedButton(QtWidgets.QPushButton):
    """胶囊按钮：primary 橙红 / soft 浅橙 / ghost 白底描边"""

    def __init__(self, text, kind="ghost", icon=None, parent=None, clicked=None):
        super().__init__(text, parent)
        self.setCursor(QtCore.Qt.PointingHandCursor)
        self.setMinimumHeight(36)
        if clicked is not None:
            self.clicked.connect(clicked)
        if icon:
            self.setIcon(_svg_icon(icon, "#FFFFFF" if kind == "primary" else ACCENT, 17))
            self.setIconSize(QtCore.QSize(17, 17))
        styles = {
            "primary": ("background:%s;color:#FFFFFF;border:none;" % ACCENT,
                        "background:%s;" % ACCENT_HOVER,
                        "background:%s;" % ACCENT_PRESSED),
            "soft": ("background:%s;color:%s;border:none;" % (ACCENT_SOFT, ACCENT),
                     "background:#FFE4D8;", "background:#FFD8C8;"),
            "ghost": ("background:#FFFFFF;color:%s;border:1px solid %s;" % (TEXT, BORDER),
                      "background:#F7F8FC;", "background:#EFF1F7;"),
            "danger": ("background:#FFFFFF;color:#D64545;border:1px solid #F3D7D7;",
                       "background:#FDF2F2;", "background:#FBE8E8;"),
        }
        base, hover, pressed = styles.get(kind, styles["ghost"])
        self.setStyleSheet(
            "QPushButton{%sborder-radius:12px;padding:8px 16px;font-size:13px;font-weight:500;}"
            "QPushButton:hover{%s}QPushButton:pressed{%s}"
            "QPushButton:disabled{color:%s;background:#F5F6FA;border:1px solid %s;}"
            % (base, hover, pressed, MUTED_2, BORDER))


def make_button(text, kind="ghost", icon=None, cmd=None, width=None, clicked=None):
    btn = RoundedButton(text, kind, icon, clicked=clicked if clicked is not None else cmd)
    if width:
        btn.setMinimumWidth(width)
    return btn


