class TitleBar(QtWidgets.QWidget):
    def __init__(self, parent):
        super().__init__(parent)
        self._parent = parent
        self._drag = None
        row = QtWidgets.QHBoxLayout(self)
        row.setContentsMargins(26, 14, 18, 6)
        row.setSpacing(12)

        logo = QtWidgets.QLabel()
        pm = app_wordmark()
        if not pm.isNull():
            pm = pm.scaledToHeight(68, QtCore.Qt.SmoothTransformation)
            logo.setPixmap(pm)
        logo.setFixedHeight(70)
        row.addWidget(logo)

        box = QtWidgets.QVBoxLayout()
        box.setContentsMargins(0, 0, 0, 0)
        box.setSpacing(0)
        sub = QtWidgets.QLabel("全能视频下载")
        sub.setStyleSheet("color:%s;font-size:11px;" % MUTED_2)
        box.addStretch(1)
        box.addWidget(sub)
        box.addStretch(1)
        row.addLayout(box)
        row.addStretch(1)

        self.btn_min = IconButton("min", "最小化")
        self.btn_max = IconButton("square", "最大化 / 还原")
        self.btn_close = IconButton("close", "关闭")
        self.btn_close.setStyleSheet(
            "QPushButton{background:transparent;border:none;border-radius:16px;}"
            "QPushButton:hover{background:#FDECEC;}")
        row.addWidget(self.btn_min)
        row.addWidget(self.btn_max)
        row.addWidget(self.btn_close)

    def mousePressEvent(self, event):
        if event.button() == QtCore.Qt.LeftButton:
            self._drag = event.globalPosition().toPoint() - self._parent.pos()
            event.accept()

    def mouseMoveEvent(self, event):
        if self._drag is not None and event.buttons() & QtCore.Qt.LeftButton:
            self._parent.move(event.globalPosition().toPoint() - self._drag)
            event.accept()

    def mouseReleaseEvent(self, event):
        self._drag = None

    def mouseDoubleClickEvent(self, event):
        if event.button() == QtCore.Qt.LeftButton:
            toggle = getattr(self._parent, "toggle_maximized", None)
            if toggle is not None:
                toggle()
            event.accept()


class Backdrop(QtWidgets.QWidget):
    """唯一的可视容器：白色圆角卡片 + 极淡的橙红/暖灰渐变光斑"""

    RADIUS = 22

    def __init__(self, parent=None):
        super().__init__(parent)
        self.setAttribute(QtCore.Qt.WA_TranslucentBackground, True)
        self.setAttribute(QtCore.Qt.WA_StyledBackground, False)

    def paintEvent(self, event):
        painter = QtGui.QPainter(self)
        painter.setRenderHint(QtGui.QPainter.Antialiasing)

        rect = QtCore.QRectF(self.rect()).adjusted(1.0, 1.0, -1.0, -1.0)
        clip = QtGui.QPainterPath()
        clip.addRoundedRect(rect, self.RADIUS, self.RADIUS)
        painter.setClipPath(clip)
        painter.fillRect(self.rect(), QtGui.QColor("#FFFFFF"))

        def blob(cx, cy, radius, color):
            grad = QtGui.QRadialGradient(QtCore.QPointF(cx, cy), radius)
            grad.setColorAt(0.0, color)
            edge = QtGui.QColor(color)
            edge.setAlpha(0)
            grad.setColorAt(1.0, edge)
            painter.setBrush(QtGui.QBrush(grad))
            painter.setPen(QtCore.Qt.NoPen)
            painter.drawEllipse(QtCore.QPointF(cx, cy), radius, radius)

        w, h = self.width(), self.height()
        blob(w * 0.06, h * 0.10, max(w, h) * 0.42, QtGui.QColor(255, 176, 140, 64))
        blob(w * 0.97, h * 0.90, max(w, h) * 0.40, QtGui.QColor(255, 150, 120, 44))
        blob(w * 0.86, h * 0.04, max(w, h) * 0.28, QtGui.QColor(150, 165, 230, 26))

        painter.setClipping(False)

