class _MsgBox:
    YES = True
    NO = False

    def _wrap(self, parent, text, width=380):
        box = QtWidgets.QMessageBox(parent)
        box.setTextFormat(QtCore.Qt.PlainText)
        return box

    def showinfo(self, title, text, parent=None, **_):
        box = self._wrap(parent, text)
        box.setWindowTitle(title)
        box.setIcon(QtWidgets.QMessageBox.Information)
        box.setText(str(text))
        box.exec()
        return "ok"

    def showwarning(self, title, text, parent=None, **_):
        box = self._wrap(parent, text)
        box.setWindowTitle(title)
        box.setIcon(QtWidgets.QMessageBox.Warning)
        box.setText(str(text))
        box.exec()
        return "ok"

    def showerror(self, title, text, parent=None, **_):
        box = self._wrap(parent, text)
        box.setWindowTitle(title)
        box.setIcon(QtWidgets.QMessageBox.Critical)
        box.setText(str(text))
        box.exec()
        return "ok"

    def askyesno(self, title, text, parent=None, **_):
        box = self._wrap(parent, text)
        box.setWindowTitle(title)
        box.setIcon(QtWidgets.QMessageBox.Question)
        box.setText(str(text))
        yes = box.addButton("是", QtWidgets.QMessageBox.YesRole)
        box.addButton("否", QtWidgets.QMessageBox.NoRole)
        box.setDefaultButton(yes)
        box.exec()
        return box.clickedButton() is yes


class _FileDialog:
    def askdirectory(self, initialdir=None, title=None, parent=None, **_):
        return QtWidgets.QFileDialog.getExistingDirectory(parent, title or "选择目录", initialdir or "")

    def askopenfilename(self, title=None, initialdir=None, filetypes=None, parent=None, **_):
        pattern = ";;".join("%s (%s)" % (n, f) for n, f in (filetypes or [])) or "所有文件 (*.*)"
        path, _ = QtWidgets.QFileDialog.getOpenFileName(parent, title or "选择文件", initialdir or "", pattern)
        return path


