    def configure(self, state=None, **_):
        self.w.setReadOnly(state != "normal")

    config = configure

    def insert(self, _index="end", text=""):
        self.w.moveCursor(QtGui.QTextCursor.End)
        self.w.insertPlainText(str(text))
        self.w.moveCursor(QtGui.QTextCursor.End)

