# ============================ 窗口根对象 ============================
class _EdgeCursorTracker(QtCore.QObject):
    """常驻全局鼠标跟踪：光标形状始终是鼠标位置的纯函数（边缘=resize，卡片内=箭头）"""

    def __init__(self, root):
        super().__init__()
        self._root = root

    def eventFilter(self, obj, event):
        etype = event.type()
        if etype == QtCore.QEvent.MouseMove:
            if obj is self._root or self._root.isAncestorOf(obj):
                self._root._update_edge_cursor(
                    self._root.mapFromGlobal(event.globalPosition().toPoint()))
            return False
        if etype == QtCore.QEvent.ApplicationDeactivate:
            self._root.unsetCursor()
            return False
        return False


class _MouseTracker(QtCore.QObject):
    """resize 拖拽期间的全局鼠标跟踪：光标移出窗口也能继续拉伸"""

    def __init__(self, root):
        super().__init__()
        self._root = root

    def eventFilter(self, obj, event):
        if not self._root._resize_edges:
            return False
        etype = event.type()
        if etype == QtCore.QEvent.MouseMove:
            self._root._apply_resize(event.globalPosition().toPoint())
            return True
        if etype == QtCore.QEvent.MouseButtonRelease:
            self._root._end_resize()
            return True
        if etype == QtCore.QEvent.ApplicationDeactivate:
            self._root._end_resize()
            return True
        return False


class ResizeHandle(QtWidgets.QWidget):
    """贴在可见卡片边缘的透明拉伸手柄（8px 边 / 8x8 角）"""

    CURSORS = {
        (True, False, False, False): QtCore.Qt.SizeVerCursor,
        (False, False, False, True): QtCore.Qt.SizeVerCursor,
        (False, True, False, False): QtCore.Qt.SizeHorCursor,
        (False, False, True, False): QtCore.Qt.SizeHorCursor,
        (True, True, False, False): QtCore.Qt.SizeFDiagCursor,
        (True, False, True, False): QtCore.Qt.SizeBDiagCursor,
        (False, True, False, True): QtCore.Qt.SizeFDiagCursor,
        (False, False, True, True): QtCore.Qt.SizeFDiagCursor,
    }

    def __init__(self, edges, parent):
        super().__init__(parent)
        self._edges = edges

    def mousePressEvent(self, event):
        if event.button() == QtCore.Qt.LeftButton:
            root = self.window()
            if hasattr(root, "start_edge_resize"):
                root.start_edge_resize(self._edges, event.globalPosition().toPoint())
                event.accept()
            return
        super().mousePressEvent(event)


class _RootWindow(QtWidgets.QWidget):
    """宿主窗口：提供 Tk 风格的 after/destroy/clipboard 等接口"""

    stateChanged = QtCore.Signal(bool)

    def __init__(self):
        super().__init__()
        self._dispatcher = _Dispatcher()
        self._clip = QtWidgets.QApplication.clipboard()
        self._maximized = False
        self._normal_geometry = None
        self._resize_edges = None
        self._resize_origin = None
        self._tracker = None
        self._handles = []
        self.setMouseTracking(True)
        self._cursor_tracker = _EdgeCursorTracker(self)
        QtWidgets.QApplication.instance().installEventFilter(self._cursor_tracker)

    # ---- 无边框窗口：边缘拖拽改变大小 ----
    def add_resize_handle(self, handle):
        self._handles.append(handle)
        self._layout_handles()

    def _layout_handles(self):
        # 手柄覆盖卡片外侧阴影带，并向卡片边缘内伸 EDGE_OVERLAP，让可见卡片边缘可直接抓住
        e = SHADOW_MARGIN + EDGE_OVERLAP
        w, h = self.width(), self.height()
        for handle in self._handles:
            top, left, right, bottom = handle._edges
            if top and left:
                x, y, ww, hh = 0, 0, e, e
            elif top and right:
                x, y, ww, hh = w - e, 0, e, e
            elif bottom and left:
                x, y, ww, hh = 0, h - e, e, e
            elif bottom and right:
                x, y, ww, hh = w - e, h - e, e, e
            elif top:
                x, y, ww, hh = e, 0, w - 2 * e, e
            elif bottom:
                x, y, ww, hh = e, h - e, w - 2 * e, e
            elif left:
                x, y, ww, hh = 0, e, e, h - 2 * e
            else:
                x, y, ww, hh = w - e, e, e, h - 2 * e
            handle.move(x, y)
            handle.resize(ww, hh)

    def resizeEvent(self, event):
        self._layout_handles()
        super().resizeEvent(event)

    def _apply_resize(self, pos):
        top, left, right, bottom = self._resize_edges
        geo = QtCore.QRect(self._normal_geometry)
        dx = pos.x() - self._resize_origin.x()
        dy = pos.y() - self._resize_origin.y()
        if left:
            geo.setLeft(min(geo.left() + dx, geo.right() - self.minimumWidth()))
        if right:
            geo.setRight(max(geo.right() + dx, geo.left() + self.minimumWidth()))
        if top:
            geo.setTop(min(geo.top() + dy, geo.bottom() - self.minimumHeight()))
        if bottom:
            geo.setBottom(max(geo.bottom() + dy, geo.top() + self.minimumHeight()))
        self.setGeometry(geo)

    def mousePressEvent(self, event):
        super().mousePressEvent(event)

    def mouseReleaseEvent(self, event):
        if self._resize_edges:
            self._end_resize()
            event.accept()
            return
        super().mouseReleaseEvent(event)

    def start_edge_resize(self, edges, global_pos):
        if self._maximized:
            return
        self._resize_edges = edges
        self._resize_origin = global_pos
        self._normal_geometry = self.geometry()
        if self._tracker is None:
            self._tracker = _MouseTracker(self)
            QtWidgets.QApplication.instance().installEventFilter(self._tracker)

    def _update_edge_cursor(self, pos):
        if self._maximized:
            self.unsetCursor()
            return
        e = SHADOW_MARGIN + EDGE_OVERLAP
        x, y = pos.x(), pos.y()
        w, h = self.width(), self.height()
        top, left, right, bottom = y < e, x < e, x >= w - e, y >= h - e
        if not (top or left or right or bottom):
            self.unsetCursor()
            return
        cur = ResizeHandle.CURSORS.get((top, left, right, bottom))
        if cur is not None:
            self.setCursor(cur)
        else:
            self.unsetCursor()

    def _end_resize(self):
        self._resize_edges = None
        if self._tracker is not None:
            QtWidgets.QApplication.instance().removeEventFilter(self._tracker)
            self._tracker = None
        self._update_edge_cursor(self.mapFromGlobal(QtGui.QCursor.pos()))

    def changeEvent(self, event):
        if event.type() == QtCore.QEvent.WindowStateChange:
            self._maximized = bool(self.windowState() & QtCore.Qt.WindowMaximized)
            self.setProperty("maximized", self._maximized)
            for widget in self.findChildren(QtWidgets.QSizeGrip):
                widget.setVisible(not self._maximized)
            for handle in self.findChildren(ResizeHandle):
                handle.setVisible(not self._maximized)
            if self._maximized:
                self.unsetCursor()
            self._sync_resize_margin()
            self.stateChanged.emit(self._maximized)
        super().changeEvent(event)

    def _sync_resize_margin(self):
        layout = self.layout()
        if layout is None:
            return
        m = 0 if self._maximized else SHADOW_MARGIN
        layout.setContentsMargins(m, m, m, m)

    def toggle_maximized(self):
        if self._maximized:
            self.showNormal()
        else:
            self.showMaximized()

    def after(self, ms, fn=None, *args):
        if fn is None:
            return
        if threading.current_thread() is threading.main_thread():
            QtCore.QTimer.singleShot(int(ms), lambda: self._safe(fn, args))
        else:
            self._dispatcher.call.emit(fn, args)

    @staticmethod
    def _safe(fn, args):
        try:
            fn(*args)
        except Exception:
            pass

    def destroy(self):
        win = self.window()
        win.close()

    def clipboard_get(self):
        text = self._clip.text()
        if not text:
            raise TclError("empty clipboard")
        return text

    def clipboard_clear(self):
        self._clip.clear()

    def clipboard_append(self, text):
        self._clip.setText(str(text))

    def update(self):
        QtWidgets.QApplication.processEvents()


def _dialog(parent, title, w, h, min_w=None, min_h=None):
    """圆角卡片式模态弹窗"""
    dlg = QtWidgets.QDialog(parent)
    dlg.setWindowTitle(title)
    dlg.setModal(True)
    dlg.resize(w, h)
    if min_w and min_h:
        dlg.setMinimumSize(min_w, min_h)
    dlg.setStyleSheet(
        "QDialog{background:%s;}QLabel{color:%s;font-size:13px;}" % (BG, TEXT))
    outer = QtWidgets.QVBoxLayout(dlg)
    outer.setContentsMargins(SHADOW_MARGIN, SHADOW_MARGIN, SHADOW_MARGIN, SHADOW_MARGIN)
    card = Card(dlg, radius=18, padding=20, spacing=12)
    outer.addWidget(card)
    dlg._card = card
    return dlg


# ============================ 主应用 ============================
class App:
    def __init__(self, root):
        self.root = root
        self.settings = load_settings()
        self.proc = None
        self.cancel_requested = False
        self.busy = False
        self._tail = []
        self._wx_started_by_us = False
        self._wx_progress_win = None

        self._init_window()
        self._style()
        self._build_ui()
        self._apply_settings()
        self.root.after(600, self._maybe_show_welcome)
        self.root.after(800, self._wx_recover_proxy)
        self.root.after(1200, self._refresh_wx_status)
        self.root.after(2000, self._auto_check_updates)

    # ---------------- 窗口 ----------------
    def _init_window(self):
        self.root.setWindowTitle(APP_TITLE)
        self.root.setWindowIcon(app_icon())
        self.root.setWindowFlag(QtCore.Qt.FramelessWindowHint, True)
        self.root.setAttribute(QtCore.Qt.WA_TranslucentBackground, True)
        self.root.setMinimumSize(1000, 720)
        screen = QtWidgets.QApplication.primaryScreen().availableGeometry()
        w = min(1180, screen.width() - 60)
        h = min(880, screen.height() - 80)
        self.root.resize(w, h)
        self.root.move(screen.x() + (screen.width() - w) // 2,
                       screen.y() + (screen.height() - h) // 2)
        self.root.setStyleSheet(
            "QWidget{font-family:'%s';color:%s;}"
            "QToolTip{background:#2B3040;color:#FFFFFF;border:none;padding:6px 9px;border-radius:8px;}"
            % (UI_FONT, TEXT))

    def _style(self):
        # Qt 版本使用样式表，无需 ttk 主题
        pass

    # ---------------- 布局 ----------------
    def _build_ui(self):
        backdrop = Backdrop(self.root)
        self.backdrop = backdrop
        outer = QtWidgets.QVBoxLayout(self.root)
        outer.setContentsMargins(SHADOW_MARGIN, SHADOW_MARGIN, SHADOW_MARGIN, SHADOW_MARGIN)
        outer.setSpacing(0)
        outer.addWidget(backdrop)
        _shadow(backdrop, blur=44, dy=12, alpha=40, color=(96, 84, 120))

        inner = QtWidgets.QVBoxLayout(backdrop)
        inner.setContentsMargins(0, 0, 0, 0)
        inner.setSpacing(0)

        self.titlebar = TitleBar(self.root)
        self.titlebar.btn_min.clicked.connect(self.root.window().showMinimized)
        self.titlebar.btn_max.clicked.connect(self.root.toggle_maximized)
        self.titlebar.btn_close.clicked.connect(self.on_close)
        self.root.stateChanged.connect(self._on_window_state)
        inner.addWidget(self.titlebar)

        body = QtWidgets.QHBoxLayout()
        body.setContentsMargins(0, 0, 0, 0)
        body.setSpacing(0)
        inner.addLayout(body, 1)

        body.addWidget(self._build_sidebar())

        content = QtWidgets.QWidget()
        content.setStyleSheet("background:transparent;")
        self.content_layout = QtWidgets.QVBoxLayout(content)
        self.content_layout.setContentsMargins(18, 6, 22, 16)
        self.content_layout.setSpacing(12)
        body.addWidget(content, 1)

        self.stack = QtWidgets.QStackedWidget()
        self.stack.setStyleSheet("background:transparent;")
        self.content_layout.insertWidget(0, self.stack, 1)

        self._build_statusbar()
        self.content_layout.addWidget(self._build_actions_card())

        self.pages = {}
        self._build_home_page()
        self._build_setup_page()
        self._build_cookie_page()
        self._build_wx_page()
        self._build_log_page()
        self._build_about_page()

        self.stack.setMinimumHeight(140)
        self._install_resize_handles()

        self.nav_buttons["home"].setChecked(True)
        self._on_nav("home")

    def _landscape_page(self, left, right, ratio=(3, 2)):
        """两栏横版页面：左右各放若干卡片，模块数量少、留白充足"""
        page = QtWidgets.QWidget()
        page.setStyleSheet("background:transparent;")
        row = QtWidgets.QHBoxLayout(page)
        row.setContentsMargins(0, 0, 0, 0)
        row.setSpacing(14)

        for items, stretch in ((left, ratio[0]), (right, ratio[1])):
            box = QtWidgets.QVBoxLayout()
            box.setContentsMargins(0, 0, 0, 0)
            box.setSpacing(14)
            for item in items:
                if isinstance(item, QtWidgets.QLayout):
                    box.addLayout(item)
                else:
                    box.addWidget(item)
            box.addStretch(1)
            wrap = QtWidgets.QWidget()
            wrap.setStyleSheet("background:transparent;")
            wrap.setLayout(box)
            row.addWidget(wrap, stretch)
        return page

    def _scrollable(self, page):
        """页面滚动容器：窗口缩小、内容放不下时自动出现纵向滚动条"""
        area = QtWidgets.QScrollArea()
        area.setFrameShape(QtWidgets.QFrame.Shape.NoFrame)
        area.setWidgetResizable(True)
        area.setHorizontalScrollBarPolicy(QtCore.Qt.ScrollBarAlwaysOff)
        area.setVerticalScrollBarPolicy(QtCore.Qt.ScrollBarAsNeeded)
        area.setWidget(page)
        area.setStyleSheet(
            "QScrollArea{background:transparent;border:none;}"
            "QScrollArea>QWidget>QWidget{background:transparent;}"
            "QScrollBar:vertical{background:transparent;width:8px;margin:2px 4px 2px 0;}"
            "QScrollBar::handle:vertical{background:#D9DCE5;border-radius:4px;min-height:48px;}"
            "QScrollBar::handle:vertical:hover{background:#C4C9D6;}"
            "QScrollBar::add-line:vertical,QScrollBar::sub-line:vertical{height:0;}"
            "QScrollBar::add-page:vertical,QScrollBar::sub-page:vertical{background:transparent;}")
        return area

    def _install_resize_handles(self):
        """放置 8 个透明拉伸手柄：覆盖卡片外侧阴影带并伸入卡片边缘，卡片内容区不受影响"""
        for edges in ((True, False, False, False), (False, True, False, False),
                      (False, False, True, False), (False, False, False, True),
                      (True, True, False, False), (True, False, True, False),
                      (False, True, False, True), (False, False, True, True)):
            handle = ResizeHandle(edges, self.root)
            self.root.add_resize_handle(handle)

    def _on_window_state(self, maximized):
        icon = "restore" if maximized else "square"
        self.titlebar.btn_max.setIcon(_svg_icon(icon, MUTED, 16))
        self.titlebar.btn_max.setToolTip("还原窗口" if maximized else "最大化")

