    def _on_template_preset(self, index):
        """选择预设后写入模板输入框；手工改动模板后预设自动切回“自定义”"""
        if 0 <= index < len(TEMPLATE_PRESETS):
            self.template_var.w.setText(TEMPLATE_PRESETS[index][1])

    def _sync_template_preset(self):
        names = [name for name, _ in TEMPLATE_PRESETS] + ["自定义"]
        index = names.index(_template_preset_name(self.template_var.get()))
        if index != self.template_preset_var.w.currentIndex():
            self.template_preset_var.w.blockSignals(True)
            self.template_preset_var.w.setCurrentIndex(index)
            self.template_preset_var.w.blockSignals(False)

    def _on_sub_lang_preset(self, index):
        """选择预设后写入语言输入框；手工改动后预设自动切回“自定义”"""
        if 0 <= index < len(SUB_LANG_PRESETS):
            self.sub_lang_var.w.setText(SUB_LANG_PRESETS[index][1])

    def _sync_sub_lang_preset(self):
        names = [name for name, _ in SUB_LANG_PRESETS] + ["自定义"]
        index = names.index(_sub_lang_preset_name(self.sub_lang_var.get().strip()))
        if index != self.sub_lang_preset_var.w.currentIndex():
            self.sub_lang_preset_var.w.blockSignals(True)
            self.sub_lang_preset_var.w.setCurrentIndex(index)
            self.sub_lang_preset_var.w.blockSignals(False)

