    # ---------------- 设置同步 ----------------
    def _apply_settings(self):
        s = self.settings
        self.quality_var.set(s["quality"] if s["quality"] in QUALITIES else QUALITIES[0])
        self.audio_var.set(s["audio_quality"] if s["audio_quality"] in AUDIO_QUALITIES else "最佳")
        self.container_var.set(s["container"] if s["container"] in CONTAINERS else "自动")
        self.dir_var.set(s["download_dir"] or default_download_dir())
        self.template_var.set(s["template"] or DEFAULT_TEMPLATE)
        self._sync_template_preset()
        self.subs_var.set(bool(s["subs"]))
        self.convert_var.set(bool(s["convert_subs"]))
        self.thumb_var.set(bool(s["thumbnail"]))
        self.no_playlist_var.set(bool(s.get("no_playlist")))
        self.sub_lang_var.set(s["sub_lang"] or "zh,en")
        self._sync_sub_lang_preset()
        self.cookie_mode_var.set(s["cookie_mode"] if s["cookie_mode"] in ("file", "browser", "none") else "file")
        self.cookie_file_var.set(s["cookie_file"] or "")
        self.browser_var.set(s["browser"] if s["browser"] in BROWSERS else "Edge")
        self.wx_auto_var.set(bool(s.get("wxchannels_auto_start", True)))
        self.wx_keep_proxy_var.set(bool(s.get("wxchannels_keep_system_proxy", True)))
        self.wx_action_var.set(s.get("wxchannels_existing_action")
                               if s.get("wxchannels_existing_action") in WXCHANNELS_EXISTING_ACTIONS else "skip")
        self._update_cookie_ui()

    def _update_cookie_ui(self):
        mode = self.cookie_mode_var.get()
        self.cookie_file_frame.setVisible(mode == "file")
        self.browser_frame.setVisible(mode == "browser")

    def _capture_settings(self):
        s = self.settings
        s["quality"] = self.quality_var.get()
        s["audio_quality"] = self.audio_var.get()
        s["container"] = self.container_var.get()
        s["download_dir"] = self.dir_var.get().strip()
        s["template"] = self.template_var.get().strip() or DEFAULT_TEMPLATE
        s["subs"] = bool(self.subs_var.get())
        s["convert_subs"] = bool(self.convert_var.get())
        s["thumbnail"] = bool(self.thumb_var.get())
        s["no_playlist"] = bool(self.no_playlist_var.get())
        s["sub_lang"] = self.sub_lang_var.get().strip() or "zh,en"
        s["cookie_mode"] = self.cookie_mode_var.get()
        s["cookie_file"] = self.cookie_file_var.get().strip()
        s["browser"] = self.browser_var.get()
        s["wxchannels_auto_start"] = bool(self.wx_auto_var.get())
        s["wxchannels_keep_system_proxy"] = bool(self.wx_keep_proxy_var.get())
        s["wxchannels_existing_action"] = self.wx_action_var.get() or "skip"

    def _save_current_settings(self):
        self._capture_settings()
        save_settings(self.settings)

    def _get_urls(self):
        urls = []
        for line in self.url_text.get().splitlines():
            line = line.strip()
            if line and line not in urls:
                urls.append(line)
        return urls

    # ---------------- 文件与剪贴板 ----------------
    def on_paste(self):
        try:
            clip = self.root.clipboard_get()
        except TclError:
            messagebox.showinfo("提示", "剪贴板中没有可粘贴的内容", self.root)
            return
        if clip:
            self.url_text.insert("end", clip)

    def on_browse_dir(self):
        d = filedialog.askdirectory(initialdir=self.dir_var.get() or default_download_dir(),
                                    title="选择下载目录", parent=self.root)
        if d:
            self.dir_var.set(d)

    def on_open_dir(self):
        d = self.dir_var.get().strip()
        try:
            if d and not os.path.isdir(d):
                os.makedirs(d, exist_ok=True)
            os.startfile(d or default_download_dir())
        except Exception as e:
            messagebox.showerror("错误", str(e), self.root)

    def on_browse_cookie(self):
        f = filedialog.askopenfilename(
            title="选择 cookies.txt", initialdir=str(app_dir()),
            filetypes=[("Netscape Cookies", "*.txt"), ("所有文件", "*.*")], parent=self.root)
        if f:
            self.cookie_file_var.set(f)

    def on_open_cookie_file(self):
        f = self.cookie_file_var.get().strip()
        if not f or not Path(f).exists():
            f = str(app_dir() / "cookies.txt")
        if Path(f).exists():
            try:
                os.startfile(f)
                return
            except Exception:
                pass
        messagebox.showinfo("提示", "还没有 cookies.txt 文件，请先导出（点“如何获取 Cookies？”查看方法）", self.root)

    def _open_url(self, url):
        try:
            os.startfile(url)
        except Exception:
            try:
                exe = find_browser_exe(self.browser_var.get().lower())
                if exe and os.path.exists(exe):
                    subprocess.Popen([exe, url], creationflags=getattr(subprocess, "CREATE_NO_WINDOW", 0))
                    return
            except Exception:
                pass
            messagebox.showerror("错误", "无法打开链接，请手动复制到浏览器地址栏：%s" % url, self.root)

    def _copy_text(self, content):
        try:
            self.root.clipboard_clear()
            self.root.clipboard_append(content)
            messagebox.showinfo("已复制", "说明文字已复制到剪贴板", self.root)
        except Exception as e:
            messagebox.showerror("错误", "复制失败：%s" % e, self.root)

    def _center_popup(self, win, w, h):
        win.resize(w, h)

    # ---------------- 浏览器 / Cookie ----------------
    def _is_browser_running(self, browser):
        names = {"chrome": "chrome.exe", "edge": "msedge.exe", "firefox": "firefox.exe",
                 "brave": "brave.exe", "opera": "opera.exe", "vivaldi": "vivaldi.exe"}
        name = names.get(browser)
        if not name:
            return False
        try:
            out = subprocess.run(["tasklist", "/FI", "IMAGENAME eq %s" % name],
                                 capture_output=True, text=True,
                                 creationflags=getattr(subprocess, "CREATE_NO_WINDOW", 0)).stdout
            return name.lower() in out.lower()
        except Exception:
            return False

    def _close_browser(self, browser):
        names = {"chrome": "chrome.exe", "edge": "msedge.exe", "firefox": "firefox.exe",
                 "brave": "brave.exe", "opera": "opera.exe", "vivaldi": "vivaldi.exe"}
        name = names.get(browser)
        if not name:
            return False
        flags = getattr(subprocess, "CREATE_NO_WINDOW", 0)
        subprocess.run(["taskkill", "/IM", name], capture_output=True, creationflags=flags)
        for _ in range(24):
            if not self._is_browser_running(browser):
                return True
            time.sleep(0.5)
        subprocess.run(["taskkill", "/F", "/IM", name], capture_output=True, creationflags=flags)
        time.sleep(1)
        return not self._is_browser_running(browser)

    def on_quick_cookie(self):
        """下载页快捷按钮：按当前浏览器设置一键获取 Cookie 并自动启用"""
        self._save_current_settings()
        browser = self.browser_var.get().lower()
        if browser in ("chrome", "edge"):
            display = "Chrome" if browser == "chrome" else "Edge"
            if not self._is_browser_running(browser):
                self.append_log("未检测到 %s 正在运行，正在为你打开 ..." % display)
                try:
                    exe = find_browser_exe(browser)
                    if exe:
                        os.startfile(exe)
                except Exception:
                    pass
            threading.Thread(target=self._grab_cdp_flow, args=(browser,), daemon=True).start()
            return
        urls = self._get_urls()
        args = [find_ytdlp(), "--ignore-config", "--cookies-from-browser", browser,
                "--simulate", "--skip-download"]
        args += [urls[0]] if urls else ["https://www.youtube.com"]
        self.append_log("正在从 %s 读取 Cookie ..." % browser)

        def _done(rc):
            if rc == 0:
                self.cookie_mode_var.set("browser")
                self._update_cookie_ui()
                self.append_log("✓ Cookie 读取成功，已自动启用“从浏览器获取”")
            else:
                self.append_log("✗ Cookie 读取失败（浏览器可能未登录目标网站），可改用 cookies.txt 文件方式")

        threading.Thread(target=self._run_worker, args=(args, False, _done), daemon=True).start()

    def on_grab_cookie(self):
        self._save_current_settings()
        mode = self.cookie_mode_var.get()
        browser = self.browser_var.get().lower()
        if mode == "file":
            ok = messagebox.askyesno(
                "重新获取",
                "当前正在使用 cookies.txt。\n\n是否从浏览器重新获取最新 Cookie？\n（推荐，可避免 Cookie 过期导致下载失败）",
                self.root)
            if not ok:
                f = self.cookie_file_var.get().strip()
                if f and Path(f).exists():
                    self.append_log("正在校验 cookies.txt ...")
                    args = [find_ytdlp(), "--ignore-config", "--cookies", f, "--simulate", "--skip-download"]
                    args += self._get_urls()[:1] or ["https://www.youtube.com"]
                    threading.Thread(target=self._run_worker, args=(args, False), daemon=True).start()
                else:
                    messagebox.showwarning("提示", "未找到 cookies.txt 文件", self.root)
                return
        if mode == "none":
            messagebox.showinfo("提示", "当前选择“不使用”Cookie。如需获取，请选择“从浏览器获取”或“使用 cookies.txt 文件”。", self.root)
            return
        if browser in ("chrome", "edge"):
            display = "Chrome" if browser == "chrome" else "Edge"
            if not self._is_browser_running(browser):
                self.append_log("未检测到 %s 正在运行，正在为你打开 ..." % display)
                try:
                    exe = find_browser_exe(browser)
                    if exe:
                        os.startfile(exe)
                except Exception:
                    pass
            threading.Thread(target=self._grab_cdp_flow, args=(browser,), daemon=True).start()
        else:
            args = [find_ytdlp(), "--ignore-config", "--cookies-from-browser", browser, "--simulate", "--skip-download"]
            args += self._get_urls()[:1] or ["https://www.youtube.com"]
            self.append_log("正在从 %s 读取 Cookie ..." % browser)
            threading.Thread(target=self._run_worker, args=(args, False), daemon=True).start()

    def _grab_cdp_flow(self, browser):
        try:
            self.set_busy(True)
            display = "Chrome" if browser == "chrome" else "Edge"
            self.append_log("正在连接运行中的 %s（端口 9222）..." % display)
            deadline = time.time() + 30
            port, dpath = None, None
            while time.time() < deadline:
                port, dpath = read_devtools_active_port(browser)
                if port:
                    break
                time.sleep(1)
            if not port:
                url = ("chrome://inspect/#remote-debugging" if browser == "chrome"
                       else "edge://inspect/#remote-debugging")
                self.append_log("✗ 未发现 %s 的调试端口" % display)
                self.append_log("请按以下步骤开启（只需一次）：")
                self.append_log("1. 打开 %s，地址栏输入 %s 并回车" % (display, url))
                self.append_log("2. 打开 Remote debugging 下的“Allow remote debugging for this browser instance”开关")
                self.append_log("3. 保持 %s 运行，重新点击“获取Cookie”" % display)

                def _ask_open(d=display):
                    if messagebox.askyesno(
                            "需要开启浏览器调试开关",
                            "请打开 %s 的 Remote debugging 下的“Allow remote debugging for this browser instance”开关，\n"
                            "保持浏览器运行，然后重新点击“获取Cookie”。\n\n"
                            "（若浏览器弹出“允许远程调试？”，请点击允许）\n\n"
                            "是否现在为你打开设置页面？" % d, self.root):
                        self.on_open_debug_settings()
                self.root.after(0, _ask_open)
                return
            self.append_log("✓ 已连接 %s（端口 %d）" % (display, port))
            text, err = grab_browser_cookies(browser, COOKIE_URLS)
            if err:
                self.append_log("✗ " + err)
                return
            n = len([l for l in text.splitlines() if l and not l.startswith("#")])
            out = app_dir() / "cookies.txt"
            out.write_text(text, encoding="utf-8")

            def _done():
                self.cookie_file_var.set(str(out))
                self.cookie_mode_var.set("file")
                self._update_cookie_ui()
            self.root.after(0, _done)
            self.append_log("✓ 已获取 %d 条 Cookie，已保存为 cookies.txt 并自动启用" % n)
        except Exception as e:
            self.append_log("✗ 获取 Cookie 出错：%s" % e)
        finally:
            self.set_busy(False)

    def on_open_debug_settings(self):
        browser = self.browser_var.get().lower()
        display = "Chrome" if browser == "chrome" else "Edge"
        url = "edge://inspect/#remote-debugging" if browser == "edge" else "chrome://inspect/#remote-debugging"
        try:
            port, path = read_devtools_active_port(browser)
            if port and open_page_via_debug(port, path, url):
                self.append_log("已在 %s 中打开调试设置页面" % display)
                return
        except Exception:
            pass
        exe = find_browser_exe(browser)
        if self._is_browser_running(browser):
            try:
                os.startfile(url)
                self.append_log("已打开调试设置页面：%s" % url)
                return
            except Exception:
                pass
        if exe and os.path.exists(exe):
            try:
                subprocess.Popen([exe, url], creationflags=getattr(subprocess, "CREATE_NO_WINDOW", 0))
                self.append_log("已打开调试设置页面：%s" % url)
                return
            except Exception:
                pass
        messagebox.showerror("错误", "无法自动打开设置页面，请手动在浏览器地址栏输入：%s" % url, self.root)

    def on_check_browser_cookie(self):
        self._save_current_settings()
        urls = self._get_urls()
        browser = self.browser_var.get().lower()
        args = [find_ytdlp(), "--ignore-config", "--cookies-from-browser", browser,
                "--simulate", "--skip-download"]
        args += [urls[0]] if urls else ["https://www.youtube.com"]
        self.append_log("正在检测浏览器 Cookie ...")
        threading.Thread(target=self._run_worker, args=(args, False), daemon=True).start()

