    # ---------------- 微信视频号 ----------------
    def _wx_recover_proxy(self):
        def work():
            try:
                wxchannels_recover_system_proxy(log=self.append_log)
            except Exception:
                pass
        threading.Thread(target=work, daemon=True).start()

    def _refresh_wx_status(self):
        def work():
            if not wxchannels_engine_installed():
                state = "未安装（点“安装/更新视频号引擎”即可）"
                tone = "muted"
            else:
                ver = wxchannels_engine_version() or "未知版本"
                if wxchannels_api_alive():
                    state = "运行中（引擎 %s）" % ver
                    tone = "ok"
                else:
                    state = "已安装未运行（引擎 %s）" % ver
                    tone = "warn"
            text = "视频号服务：" + state
            self.root.after(0, lambda: self._set_wx_status(text, tone))
        threading.Thread(target=work, daemon=True).start()

    def _set_wx_status(self, text, tone="muted"):
        self.wx_status_var.set(text)
        self.side_status.setText(text)
        colors = {"ok": ("#E8F7EF", "#1E9E63"), "warn": ("#FFF4E5", "#D98A00"),
                  "muted": ("#F2F4F8", MUTED)}
        bg, fg = colors.get(tone, colors["muted"])
        self.wx_pill.setText({"ok": "运行中", "warn": "未运行"}.get(tone, "未检测"))
        self.wx_pill.setStyleSheet(
            "background:%s;color:%s;border-radius:10px;padding:3px 10px;font-size:11px;" % (bg, fg))

    def _wx_prepare_service(self, auto_install=None):
        auto_install = self.wx_auto_var.get() if auto_install is None else auto_install
        if not wxchannels_engine_installed():
            if not auto_install:
                return False, "视频号引擎尚未安装，请先点“安装/更新视频号引擎”"
            self.append_log("检测到未安装视频号引擎，开始自动下载 ...")
            ok, ver = install_wxchannels_engine(log=self.append_log)
            if not ok:
                return False, ver
        if wxchannels_api_alive():
            return True, None
        self.append_log("正在启动视频号服务 ...")
        ok, err = start_wxchannels_engine(
            self.settings["download_dir"],
            keep_system_proxy=self.wx_keep_proxy_var.get(),
            log=self.append_log)
        if not ok:
            return False, err
        self._wx_started_by_us = True
        return True, None

    def on_wx_install(self):
        self.append_log("=" * 60)
        self._refresh_wx_status()

        def work():
            ok, msg = install_wxchannels_engine(log=self.append_log)
            if not ok:
                self.append_log("✗ " + msg)
                self.root.after(0, lambda: messagebox.showerror("视频号引擎", msg, self.root))
            else:
                self.append_log("✓ 视频号引擎安装完成，版本 %s" % msg)
            self._refresh_wx_status()
        threading.Thread(target=work, daemon=True).start()

    def on_wx_start(self):
        self._save_current_settings()
        self.append_log("=" * 60)

        def work():
            ok, err = self._wx_prepare_service()
            if ok:
                self.append_log("✓ 视频号服务已就绪，地址 %s" % WXCHANNELS_PANEL_URL)
                self.append_log("提示：请在微信中打开“视频号”，双击把视频号"
                                "分离成独立窗口并播放任意视频，再回到本软件下载视频号链接。")
            else:
                self.append_log("✗ " + err)
                self.root.after(0, lambda: messagebox.showerror("视频号服务", err, self.root))
            self._refresh_wx_status()
        threading.Thread(target=work, daemon=True).start()

    def on_wx_stop(self):
        def work():
            self.append_log("正在停止视频号服务 ...")
            ok = stop_wxchannels_engine(log=self.append_log)
            self._wx_started_by_us = False
            self.append_log("✓ 视频号服务已停止" if ok else "✗ 视频号服务停止失败")
            self._refresh_wx_status()
        threading.Thread(target=work, daemon=True).start()

    def on_wx_panel(self):
        self._open_url(WXCHANNELS_PANEL_URL)

    def on_wx_tasks(self):
        self._save_current_settings()
        threading.Thread(target=self._wxchannels_show_tasks, daemon=True).start()

    def _wxchannels_test_flow(self, urls):
        try:
            self.set_busy(True)
            self.append_log("检测到 %d 个视频号链接，检查视频号服务 ..." % len(urls))
            ok, err = self._wx_prepare_service()
            if not ok:
                self.append_log("✗ " + err)
                return
            tasks, lerr = wxchannels_list_tasks()
            if lerr:
                self.append_log("✗ " + lerr)
                return
            self.append_log("✓ 视频号服务可用，当前共有 %d 个下载任务" % len(tasks))
            for u in urls:
                self.append_log("  视频号链接：%s" % u)
        finally:
            self._refresh_wx_status()
            self.set_busy(False)

    def _wxchannels_download_flow(self, urls):
        try:
            self.set_busy(True)
            self.append_log("检测到 %d 个视频号链接，准备视频号服务 ..." % len(urls))
            ok, err = self._wx_prepare_service()
            if not ok:
                self.append_log("✗ " + err)
                self.root.after(0, lambda: messagebox.showerror("视频号下载", err, self.root))
                return
            action = self.wx_action_var.get() or "skip"
            created = 0
            for u in urls:
                task, terr = wxchannels_create_task(
                    u, download_dir=self.settings["download_dir"],
                    existing_action=action, log=self.append_log)
                if terr:
                    self.append_log("✗ %s：%s" % (u, terr))
                    continue
                created += 1
                name = task.get("name") or "视频号视频"
                tid = task.get("id")
                self.append_log("✓ 已创建下载任务：%s（任务号 %s）" % (name, tid))
            if created:
                self.append_log("视频号下载已交给后台服务，可点“查看视频号任务”查看进度")
                self.root.after(0, self._show_wx_progress_window)
            else:
                self.append_log("✗ 未能创建任何视频号下载任务")
        finally:
            self._refresh_wx_status()
            self.set_busy(False)

    def _wxchannels_show_tasks(self):
        self.root.after(0, self._show_wx_progress_window)

    def _show_wx_progress_window(self):
        if self._wx_progress_win is not None and self._wx_progress_win.isVisible():
            self._wx_progress_win.raise_()
            return
        dlg = _dialog(self.root, "视频号下载任务", 760, 480, min_w=620, min_h=380)
        self._wx_progress_win = dlg
        card = dlg._card
        head = QtWidgets.QHBoxLayout()
        head.addWidget(SectionTitle("下载任务", "list", "每 2 秒自动刷新"))
        head.addStretch(1)
        self._wx_task_count = Pill("0 个任务", "muted")
        head.addWidget(self._wx_task_count)
        card.add_layout(head)

        table = QtWidgets.QTableWidget(0, 5)
        table.setHorizontalHeaderLabels(["任务号", "名称", "状态", "进度", "大小"])
        table.verticalHeader().setVisible(False)
        table.setShowGrid(False)
        table.setSelectionBehavior(QtWidgets.QAbstractItemView.SelectRows)
        table.setEditTriggers(QtWidgets.QAbstractItemView.NoEditTriggers)
        table.horizontalHeader().setSectionResizeMode(1, QtWidgets.QHeaderView.Stretch)
        table.setStyleSheet(
            "QTableWidget{background:#FFFFFF;border:1px solid %s;border-radius:12px;"
            "gridline-color:transparent;}"
            "QTableWidget::item{padding:7px 8px;border-bottom:1px solid #F4F6FA;}"
            "QTableWidget::item:selected{background:%s;color:%s;}"
            "QHeaderView::section{background:#FAFBFD;border:none;padding:9px 8px;"
            "color:%s;font-size:12px;font-weight:600;}" % (BORDER, ACCENT_SOFT, TEXT, MUTED))
        card.add(table, 1)

        row = QtWidgets.QHBoxLayout()
        self._wx_task_hint = QtWidgets.QLabel("正在刷新 ...")
        self._wx_task_hint.setStyleSheet("color:%s;font-size:12px;" % MUTED)
        row.addWidget(self._wx_task_hint)
        row.addStretch(1)
        row.addWidget(make_button("刷新", "ghost", "refresh", clicked=lambda: refresh()))
        row.addWidget(make_button("关闭", "primary", clicked=dlg.accept))
        card.add_layout(row)

        def fmt_size(n):
            try:
                n = float(n or 0)
            except Exception:
                return "-"
            for unit in ("B", "KB", "MB", "GB"):
                if n < 1024 or unit == "GB":
                    return ("%d B" % n) if unit == "B" else ("%.1f %s" % (n, unit))
                n /= 1024.0

        def refresh():
            if not dlg.isVisible():
                return
            tasks, err = wxchannels_list_tasks(page_size=100)
            if err:
                self._wx_task_hint.setText("刷新失败：" + err)
            else:
                tasks = sorted(tasks, key=lambda t: t.get("id", 0), reverse=True)
                table.setRowCount(len(tasks))
                for r, t in enumerate(tasks):
                    st = WXCHANNELS_TASK_STATUS.get(t.get("status"), str(t.get("status")))
                    vals = [str(t.get("id") or "-"), t.get("name") or "-", st,
                            "%d%%" % int(t.get("progress") or 0), fmt_size(t.get("size"))]
                    for c, v in enumerate(vals):
                        item = QtWidgets.QTableWidgetItem(v)
                        if c == 3:
                            item.setTextAlignment(QtCore.Qt.AlignCenter)
                        table.setItem(r, c, item)
                self._wx_task_count.setText("%d 个任务" % len(tasks))
                self._wx_task_hint.setText("最近更新 %s" % time.strftime("%H:%M:%S"))
            QtCore.QTimer.singleShot(2000, refresh)

        QtCore.QTimer.singleShot(300, refresh)
        dlg.exec()

    # ---------------- 下载 / 测试 / 更新 ----------------
    # ---------------- 抖音（浏览器拦截模式） ----------------
    def _dy_ensure_port(self, browser):
        """等待浏览器调试端口；未找到时给出与 Cookie 流程一致的指引"""
        display = "Chrome" if browser == "chrome" else "Edge"
        port = dpath = None
        deadline = time.time() + 10
        while time.time() < deadline:
            port, dpath = read_devtools_active_port(browser)
            if port:
                break
            time.sleep(1)
        if port:
            self.append_log("✓ 已连接 %s（端口 %d）" % (display, port))
            return True
        url = ("chrome://inspect/#remote-debugging" if browser == "chrome"
               else "edge://inspect/#remote-debugging")
        self.append_log("✗ 未发现 %s 的调试端口" % display)
        self.append_log("抖音下载需要真实浏览器打开视频页（借鉴“猫抓”拦截思路），请先开启（只需一次）：")
        self.append_log("1. 打开 %s，地址栏输入 %s 并回车" % (display, url))
        self.append_log("2. 打开 Remote debugging 下的“Allow remote debugging for this browser instance”开关")
        self.append_log("3. 保持 %s 运行，重新点“开始下载”" % display)

        def _ask_open(d=display):
            if messagebox.askyesno(
                    "需要开启浏览器调试开关",
                    "抖音下载需要真实浏览器打开视频页（借鉴“猫抓”拦截思路）。\n"
                    "请打开 %s 的 Remote debugging 下的“Allow remote debugging for this browser instance”开关，\n"
                    "保持浏览器运行，然后重新点“开始下载”。\n\n"
                    "（若浏览器弹出“允许远程调试？”，请点击允许）\n\n"
                    "是否现在为你打开设置页面？" % d, self.root):
                self.on_open_debug_settings()
        self.root.after(0, _ask_open)
        return False

    def _dy_download_flow(self, urls):
        def work():
            self.set_busy(True)
            self.cancel_requested = False
            self.append_log("=" * 60)
            self.append_log("开始下载（抖音） ...")
            quality = self.settings.get("quality") or QUALITIES[0]
            audio_quality = self.settings.get("audio_quality") or "最佳"
            try:
                for u in urls:
                    if self.cancel_requested:
                        self.append_log("已停止")
                        break
                    self.set_busy(True)
                    self.append_log("抖音：%s" % u)
                    audio_only = False
                    info, err = dy_resolve_video(u, log=self.append_log)
                    if info:
                        self.append_log("✓ 已解析《%s》，共 %d 个画质：%s" % (
                            info["title"], len(info["formats"]),
                            ", ".join(f["label"] for f in info["formats"])))
                        fmt, audio_only = _dy_pick_format(info, quality)
                        self.append_log("按画质设置「%s」选择：%s" % (quality, fmt["label"]))
                        title = info["title"]
                    else:
                        self.append_log("✗ API 解析失败：%s" % err)
                        self.append_log("回退到浏览器拦截模式 ...")
                        browser = self.browser_var.get().lower()
                        if browser not in ("chrome", "edge"):
                            self.append_log("✗ 抖音下载目前仅支持 Chrome / Edge，请在“下载设置”里把浏览器改为 Chrome 或 Edge")
                            continue
                        if not self._dy_ensure_port(browser):
                            continue
                        grabbed, gerr = dy_grab_video_via_browser(browser, dy_normalize_url(u), log=self.append_log)
                        if gerr:
                            self.append_log("✗ " + gerr)
                            continue
                        title = grabbed["title"]
                        fmt = {"label": "默认", "url": grabbed["url"], "size": 0, "height": 0}
                        audio_only = (quality == "仅音频")
                        self.append_log("✓ 已拦截到视频：《%s》" % title)
                    if self.cancel_requested:
                        self.append_log("已停止")
                        break
                    safe = re.sub(r'[\\/:*?"<>|\r\n]+', "_", title).strip()[:80] or "douyin_video"
                    out = os.path.join(self.settings["download_dir"], safe + ".%(ext)s")
                    # 抖音 CDN（部分节点）要求浏览器 UA + Referer，否则 403
                    args = [find_ytdlp(), "--ignore-config",
                            "--paths", "home:" + self.settings["download_dir"],
                            "-o", out, "--no-playlist",
                            "--user-agent", DY_UA,
                            "--add-header", "Referer: https://www.douyin.com/",
                            fmt["url"]]
                    if audio_only:
                        args += ["-x", "--audio-format", "mp3"]
                        cap = _AUDIO_BITRATE.get(audio_quality)
                        args += ["--audio-quality", "0" if not cap else "%dK" % cap]
                    self._run_worker(args, True, None, "下载")
            finally:
                self.set_busy(False)
        threading.Thread(target=work, daemon=True).start()

