    # ---------------- 新片场（浏览器 Cookie + 媒体 API） ----------------
    def _xpc_ensure_port(self, browser):
        """等待浏览器调试端口；未找到时给出与 Cookie 流程一致的指引"""
        display = "Chrome" if browser == "chrome" else "Edge"
        port = dpath = None
        deadline = time.time() + 10
        while time.time() < deadline:
            port, dpath = read_devtools_active_port(browser)
            if port:
                break
            time.sleep(1)
        if port:
            self.append_log("✓ 已连接 %s（端口 %d）" % (display, port))
            return True
        if _xpc_list_debug_pages():
            self.append_log("✓ 已连接 %s（经典调试端口；若提示需先打开页面，请在浏览器里打开视频链接）" % display)
            return True
        url = ("chrome://inspect/#remote-debugging" if browser == "chrome"
               else "edge://inspect/#remote-debugging")
        self.append_log("✗ 未发现 %s 的调试端口" % display)
        self.append_log("新片场下载需要真实浏览器读取会话 Cookie（4K 画质需要登录账号），请先开启（只需一次）：")
        self.append_log("1. 打开 %s，地址栏输入 %s 并回车" % (display, url))
        self.append_log("2. 打开 Remote debugging 下的“Allow remote debugging for this browser instance”开关")
        self.append_log("3. 保持 %s 运行、在浏览器里打开过新片场，重新点“开始下载”" % display)

        def _ask_open(d=display):
            if messagebox.askyesno(
                    "需要开启浏览器调试开关",
                    "新片场下载需要真实浏览器读取会话 Cookie（4K 画质需要登录账号）。\n"
                    "请打开 %s 的 Remote debugging 下的“Allow remote debugging for this browser instance”开关，\n"
                    "保持浏览器运行，然后重新点“开始下载”。\n\n"
                    "（若浏览器弹出“允许远程调试？”，请点击允许）\n\n"
                    "是否现在为你打开设置页面？" % d, self.root):
                self.on_open_debug_settings()
        self.root.after(0, _ask_open)
        return False

