        if not urls:
            messagebox.showwarning("提示", "请先输入视频链接", self.root)
            return
        self._save_current_settings()
        self.append_log("=" * 60)
        self.append_log("开始下载 ...")
        wx_urls, other_urls = split_wxchannels_urls(urls)
        dy_urls = [u for u in other_urls if is_douyin_url(u)]
        other_urls = [u for u in other_urls if not is_douyin_url(u)]
        xpc_urls = [u for u in other_urls if is_xinpianchang_url(u)]
        other_urls = [u for u in other_urls if not is_xinpianchang_url(u)]
        if wx_urls:
            threading.Thread(target=self._wxchannels_download_flow, args=(wx_urls,), daemon=True).start()
        if dy_urls:
            self._dy_download_flow(dy_urls)
        if xpc_urls:
            self._xpc_download_flow(xpc_urls)
        if other_urls:
            args = build_download_args(other_urls, self.settings)
            threading.Thread(target=self._run_worker, args=(args, True, None, "下载"), daemon=True).start()

